INSERT INTO "public"."destiny_weapons" ("id", "display_name", "item_type_display_name", "flavor_text", "bucket_type_hash", "tier_type_hash", "tier_type_name", "tier_type", "talent_grid_hash") VALUES ('1006783454', 'Timelines'' Vertex', 'Fusion Rifle', '"I give you this, to be sure that we meet again." —Lakshmi-2', '2465295065', '4008398120', 'Legendary', '5', null), ('1013434963', 'Adjudicator', 'Submachine Gun', '"Hesitation kills." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('1016668089', 'One Small Step', 'Shotgun', '"Humanity once dreamt of walking on the Moon. Such innocence." —Eris Morn', '1498876634', '4008398120', 'Legendary', '5', null), ('1018012078', 'Horror''s Least', 'Pulse Rifle', '"Some things should not be saved." —Techeun Sedia', '2465295065', '4008398120', 'Legendary', '5', null), ('1018072983', 'It Stared Back', 'Sword', 'At the edge of the universe, I stared into the infinite deep. It stared back, and was pleased. I would become the herald of its victory, and bear witness for all creation.', '953998645', '4008398120', 'Legendary', '5', null), ('1018777295', 'Motion to Vacate', 'Shotgun', '"Done cannot be undone."', '2465295065', '4008398120', 'Legendary', '5', null), ('1019000888', 'Perses-D', 'Scout Rifle', 'Clear your corners.', '1498876634', '4008398120', 'Legendary', '5', null), ('1028124540', 'The Hero''s Burden', 'Submachine Gun', 'Forged in honor of Saladin, of all that has been lost and all that remains.', '2465295065', '4008398120', 'Legendary', '5', null), ('1028582252', 'The Comedian', 'Shotgun', 'A. A ha. A ha ha ha. A ha ha ha ha ha ha ha.', '2465295065', '4008398120', 'Legendary', '5', null), ('1030895163', 'Glacioclasm', 'Fusion Rifle', 'Clear and cold, forever.', '2465295065', '4008398120', 'Legendary', '5', null), ('1034055198', 'Necrochasm', 'Auto Rifle', 'Is your Light bright enough to stand in full gaze of the Hive''s abyss?', '1498876634', '2759499571', 'Exotic', '6', null), ('1039915310', 'Non-Denouement (Adept)', 'Combat Bow', 'This isn''t the end. Not yet.', '2465295065', '4008398120', 'Legendary', '5', null), ('1046651176', 'Bottom Dollar', 'Hand Cannon', 'Never count yourself out.', '2465295065', '4008398120', 'Legendary', '5', null), ('1047932517', 'Slayer''s Fang', 'Shotgun', 'Fear neither dreams nor teeth.', '2465295065', '2759499571', 'Exotic', '6', null), ('1048266744', 'Better Devils', 'Hand Cannon', 'Angels can''t help you here.', '1498876634', '4008398120', 'Legendary', '5', null), ('1050582210', 'Greasy Luck (Adept)', 'Glaive', 'Death to the living, long life to the killers', '2465295065', '4008398120', 'Legendary', '5', null), ('1050806815', 'The Recluse', 'Submachine Gun', 'My bite will turn your sweet flesh to vile rot.', '2465295065', '4008398120', 'Legendary', '5', null), ('105164264', 'Double-Edged Answer', 'Sword', 'Everything has a cost.', '953998645', '4008398120', 'Legendary', '5', null), ('1051949956', 'Anonymous Autumn', 'Sidearm', 'A lesson in the art of falling.', '2465295065', '4008398120', 'Legendary', '5', null), ('105306149', 'Eleatic Principle', 'Machine Gun', 'Explanation leads to contradiction.', '953998645', '4008398120', 'Legendary', '5', null), ('105567493', 'Hard Truths', 'Submachine Gun', 'It never gets easier.', '1498876634', '4008398120', 'Legendary', '5', null), ('1056103557', 'Shadow Price (Adept)', 'Auto Rifle', 'A precision Auto Rifle left behind by Toland, the Shattered. It asks so little, and it offers so much.', '2465295065', '4008398120', 'Legendary', '5', null), ('1058098236', 'Timeworn Wayfarer', 'Scout Rifle', 'Rest easy.', '2465295065', '4008398120', 'Legendary', '5', null), ('1064132738', 'BrayTech Osprey (Adept)', 'Rocket Launcher', 'Expected Use Timeframe: UNKNOWN.', '953998645', '4008398120', 'Legendary', '5', null), ('1066598837', 'Relentless (Adept)', 'Pulse Rifle', '"Embrace your fate." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('1071542914', 'Horror''s Least', 'Pulse Rifle', '"Some things should not be saved." —Techeun Sedia', '2465295065', '4008398120', 'Legendary', '5', null), ('1076810832', 'Forge''s Pledge', 'Pulse Rifle', '"Say whatever you like. You''d just better be brave enough to say it to his face."  —Lady Efrideet', '2465295065', '4008398120', 'Legendary', '5', null), ('1079872540', 'Ulterior Observation', 'Machine Gun', 'A triptych with three different images. Three different mediums. Three different artists.', '953998645', '4008398120', 'Legendary', '5', null), ('1081724548', 'Rapacious Appetite', 'Submachine Gun', 'Hunt, feed, hunt again.', '1498876634', '4008398120', 'Legendary', '5', null), ('108221785', 'Riiswalker', 'Shotgun', '"No. I will not allow a Fallen to fight in the Banner, that right is reserved for Guardians alone. But if you insist, I may allow a Guardian to carry a Fallen-forged weapon into battle. You are a weaponsmith, are you not?" —Lord Saladin to an Unknown Eliksni', '1498876634', '4008398120', 'Legendary', '5', null), ('1084190509', 'Pressurized Precision', 'Fusion Rifle', 'Beware the telltale hiss of a pressure leak…', '1498876634', '4008398120', 'Legendary', '5', null), ('1084788061', 'Swift Solstice', 'Sidearm', 'Time is running short.', '2465295065', '4008398120', 'Legendary', '5', null), ('1090936013', 'The When and Where', 'Rocket Launcher', 'All of spacetime unfolds itself before you.', '953998645', '4008398120', 'Legendary', '5', null), ('1094005544', 'Mindbender''s Ambition', 'Shotgun', '"Hiraks always did like to leave an impression." —The Spider', '2465295065', '4008398120', 'Legendary', '5', null), ('1096206669', 'IKELOS_SG_v1.0.2', 'Shotgun', 'Subroutine IKELOS: Status=reinitiated.
APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('1097616550', 'Extraordinary Rendition', 'Submachine Gun', '"My warriors fight not for themselves, or even me, but for each other." —Empress Caiatl', '1498876634', '4008398120', 'Legendary', '5', null), ('1098171824', 'Oversoul Edict', 'Pulse Rifle', 'The light of the will of Crota shines down like a vast and inverse sun.', '2465295065', '4008398120', 'Legendary', '5', null), ('1099433612', 'The Doubt', 'Auto Rifle', '"Do not fear your doubts. Fight your doubts. Honor them as you would honor your enemies." —Lakshmi-2', '1498876634', '4008398120', 'Legendary', '5', null), ('1106635211', 'Last Foray', 'Sniper Rifle', 'Scouts know that the foolhardy start fights; the wise finish them.', '2465295065', '4008398120', 'Legendary', '5', null), ('1107446438', 'Servant Leader', 'Scout Rifle', 'Humanity rises by your strength.', '1498876634', '4008398120', 'Legendary', '5', null), ('1111334348', 'Ice Breaker', 'Sniper Rifle', 'Please replace these components if use causes fatal damage: HEAT SINK. MAGAZINE. OPERATOR.', '2465295065', '2759499571', 'Exotic', '6', null), ('1115104187', 'Sole Survivor', 'Sniper Rifle', 'Names mean nothing to the dead.', '2465295065', '4008398120', 'Legendary', '5', null), ('1119734784', 'Chroma Rush', 'Auto Rifle', 'Drink from the data stream.', '1498876634', '4008398120', 'Legendary', '5', null), ('1120843238', 'Plemusa-B', 'Grenade Launcher', 'You were born for this.', '953998645', '2127292149', 'Rare', '4', null), ('1120843239', 'Stampede Mk.32', 'Grenade Launcher', 'Hang on to your helmets!', '953998645', '2127292149', 'Rare', '4', null), ('1123421440', 'Epochal Integration', 'Hand Cannon', '"It is a wonder that we are still here. Keep it that way." —Osiris', '2465295065', '4008398120', 'Legendary', '5', null), ('1123433952', 'Stay Frosty', 'Pulse Rifle', 'Delivering seasonal cheer with unparalleled attention.', '1498876634', '4008398120', 'Legendary', '5', null), ('1125217994', 'New Pacific Epitaph', 'Grenade Launcher', '"This isn''t happening. This isn''t happening. This isn''t happening."', '1498876634', '4008398120', 'Legendary', '5', null), ('1128225405', 'Midnight Coup', 'Hand Cannon', 'The conspirators were too afraid to kill me—rightly so. I am the beloved father of the people, and the glorious mob would not suffer my death. My sentence was exile.', '1498876634', '4008398120', 'Legendary', '5', null), ('1135050595', 'Duty Bound (Adept)', 'Auto Rifle', '"Due respect, Commander? I was there when the Hive found us on Earth. I was there when we stopped them on Titan. And I''ll be there when we wipe them out." —Sloane', '1498876634', '4008398120', 'Legendary', '5', null), ('1137768695', 'Foregone Conclusion', 'Auto Rifle', 'This ending was inevitable.', '1498876634', '4008398120', 'Legendary', '5', null), ('1139727256', 'Just in Case', 'Sword', 'Even contingencies need contingencies.', '953998645', '4008398120', 'Legendary', '5', null), ('1141547457', 'Frontier''s Cry', 'Hand Cannon', 'The sky bled crimson as the hills carried that terrible crack.', '2465295065', '4008398120', 'Legendary', '5', null), ('1141586039', 'Unexpected Resurgence (Adept)', 'Glaive', '"Stasis was the thesis. Strand is his dissertation." —Sister Faora', '2465295065', '4008398120', 'Legendary', '5', null), ('1141927949', 'Yesteryear', 'Pulse Rifle', '"Best way to forgive is to forget." —The Drifter', '2465295065', '4008398120', 'Legendary', '5', null), ('1144014195', 'Dark Decider', 'Auto Rifle', 'The oldest, shortest words—yes and no—are those which require the most thought.', '2465295065', '4008398120', 'Legendary', '5', null), ('1150492185', 'Sole Survivor', 'Sniper Rifle', 'Names mean nothing to the dead.', '2465295065', '4008398120', 'Legendary', '5', null), ('1151688091', 'Undercurrent', 'Grenade Launcher', 'The river embraces all. Struggle is futile.', '2465295065', '4008398120', 'Legendary', '5', null), ('1157220231', 'No Survivors (Adept)', 'Submachine Gun', '"There''s not enough seats."', '2465295065', '4008398120', 'Legendary', '5', null), ('1159252500', 'Vacuna SR4', 'Scout Rifle', 'A toast to our love for danger. Fear makes victory ever sweeter.', '2465295065', '4008398120', 'Legendary', '5', null), ('1161276682', 'Redrix''s Broadsword', 'Pulse Rifle', 'The second swing is no less deadly.', '1498876634', '4008398120', 'Legendary', '5', null), ('1161561386', 'The Guiding Sight', 'Scout Rifle', 'Forged in honor of Efrideet, and all that inspires.', '1498876634', '4008398120', 'Legendary', '5', null), ('1162247618', 'Jian 7 Rifle', 'Pulse Rifle', 'Come, brothers and sisters! Let us make way for the new ruler!', '2465295065', '4008398120', 'Legendary', '5', null), ('1167153950', 'Adhortative', 'Pulse Rifle', '"So... you think you can kill a god?" —Ghost', '2465295065', '4008398120', 'Legendary', '5', null), ('1168625549', 'IKELOS_SG_v1.0.3', 'Shotgun', 'Subroutine IKELOS: Status=reinitiated.
APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('1173780905', 'The Messenger (Adept)', 'Pulse Rifle', 'The bearer of bad news.', '1498876634', '4008398120', 'Legendary', '5', null), ('1175295126', 'Hushed Whisper', 'Combat Bow', 'Quiet now, I''ll do the talking.', '1498876634', '4008398120', 'Legendary', '5', null), ('1177293325', 'Tongeren-LR3', 'Sniper Rifle', 'Long march. Stone road. Old city. Know the land.', '2465295065', '2127292149', 'Rare', '4', null), ('1177293326', 'Damietta-LR2', 'Sniper Rifle', 'Taut sails. Wide rivers. Battered towers. Watch the seas.', '2465295065', '2127292149', 'Rare', '4', null), ('1177293327', 'Aachen-LR2', 'Sniper Rifle', 'Old kings. Sharp swords. Epic songs. Take the throne.', '2465295065', '2127292149', 'Rare', '4', null), ('1178397318', 'Agrona PR4', 'Pulse Rifle', 'Do not be afraid. Our fate cannot be taken from us. It is a gift.', '2465295065', '4008398120', 'Legendary', '5', null), ('1178397319', 'Battle Scar', 'Pulse Rifle', '"Do not concern yourself with how many horns I bear." —Lord Shaxx', '1498876634', '4008398120', 'Legendary', '5', null), ('1178886909', 'Thin Line', 'Hand Cannon', 'Sometimes you forget which side you''re on.', '2465295065', '4008398120', 'Legendary', '5', null), ('1179141605', 'Felwinter''s Lie', 'Shotgun', '"I just like the name. Doesn''t mean anything." —Lord Felwinter to Lord Timur', '2465295065', '4008398120', 'Legendary', '5', null), ('1180270692', 'Quickfang', 'Sword', 'My smile is full of blades.', '953998645', '4008398120', 'Legendary', '5', null), ('1180270693', 'Eternity''s Edge', 'Sword', '"A sword is a wand that casts two spells: parry and cut." —Tarsem Sauer', '953998645', '4008398120', 'Legendary', '5', null), ('1180270694', 'Crown-Splitter', 'Sword', '"Our enemies think themselves gods and kings. Show them the error of their ways." —Callisto Yin', '953998645', '4008398120', 'Legendary', '5', null), ('1183116657', 'Glacioclasm', 'Fusion Rifle', 'Clear and cold, forever.', '2465295065', '4008398120', 'Legendary', '5', null), ('1184309824', 'Sailspy Pitchglass', 'Linear Fusion Rifle', 'There are shapes on the horizon not yet meant to be seen.', '953998645', '4008398120', 'Legendary', '5', null), ('1184692845', 'Doom of Chelchis (Harrowed)', 'Scout Rifle', '"All is silent. Nothing answers me. The hunger comes." —Chelchis, Kell of Stone', '2465295065', '4008398120', 'Legendary', '5', null), ('1187594590', 'Relentless', 'Pulse Rifle', '"Embrace your fate." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('1189790632', 'The Steady Hand', 'Hand Cannon', 'Forged in honor of Perun, and a just and unwavering resolve.', '1498876634', '4008398120', 'Legendary', '5', null), ('1193318082', 'Shoreline Dissident', 'Sniper Rifle', 'Worse things happen at sea.', '2465295065', '4008398120', 'Legendary', '5', null), ('1195725817', 'Sondok-C', 'Submachine Gun', 'Your wisdom will lead you to victory.', '1498876634', '2127292149', 'Rare', '4', null), ('1195725818', 'Whip Scorpion-3mg', 'Submachine Gun', 'I will bring you pain.', '2465295065', '2127292149', 'Rare', '4', null), ('1195725819', 'Sorrow MG2', 'Submachine Gun', 'A standard-issue Omolon weapon. City-made.', '2465295065', '3340296461', 'Common', '2', null), ('1197073834', 'Forced Memorializer', 'Scout Rifle', 'The distant memories still live under your eyelids.', '1498876634', '4008398120', 'Legendary', '5', null), ('1197486957', 'High Albedo', 'Sidearm', '"Don''t let the Light blind you to what''s right before your eyes."  —The Exo Stranger', '1498876634', '4008398120', 'Legendary', '5', null), ('1197771438', 'Lost Signal', 'Grenade Launcher', '"I think I''ve had a little too much peace and quiet." —Failsafe', '1498876634', '4008398120', 'Legendary', '5', null), ('1200414607', 'The Showrunner', 'Submachine Gun', 'Once you have one, you''ll wonder how you ever did without.', '1498876634', '4008398120', 'Legendary', '5', null), ('1200824700', 'IKELOS_HC_v1.0.2', 'Hand Cannon', 'Subroutine IKELOS: Status=reinitiated.
APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('1201528146', 'Exalted Truth (Adept)', 'Hand Cannon', '"It''s the end of the world. We don''t have another choice." —Ikora Rey', '2465295065', '4008398120', 'Legendary', '5', null), ('1201830623', 'Truth', 'Rocket Launcher', '"…is where you seek it." —Lomar', '953998645', '2759499571', 'Exotic', '6', null), ('1202007252', 'Whirling Ovation', 'Rocket Launcher', 'Forget the pain, forget the practice, forget the blisters under your dancing shoes. Your audience is waiting.', '953998645', '2759499571', 'Exotic', '6', null), ('1206729100', 'Wilderflight', 'Grenade Launcher', 'The flightless blind, venturing out into the dark. Never to return.', '2465295065', '4008398120', 'Legendary', '5', null), ('120706239', 'Word of Crota', 'Hand Cannon', 'There was life, and He spoke unto it; and it was silent, and lived no more.', '2465295065', '4008398120', 'Legendary', '5', null), ('1216130969', 'Cold Denial', 'Pulse Rifle', 'A familiar tool in the face of failure.', '1498876634', '4008398120', 'Legendary', '5', null), ('1216319404', 'Fatebringer (Timelost)', 'Hand Cannon', 'But where is your fate, and who brings it to you?', '1498876634', '4008398120', 'Legendary', '5', null), ('1218113510', 'Tusk of the Boar', 'Grenade Launcher', 'Your impending death is no reason to back down.', '1498876634', '4008398120', 'Legendary', '5', null), ('1234150730', 'Trespasser', 'Sidearm', '"You are not welcome."', '2465295065', '2759499571', 'Exotic', '6', null), ('1239700299', 'Swordbreaker (Adept)', 'Shotgun', 'If you''re going to face down a Knight with an ascendant blade, bring an ascendant gun.', '1498876634', '4008398120', 'Legendary', '5', null), ('1242785638', 'Sarpedon-D', 'Hand Cannon', 'A bloody rain. A fitting end.', '2465295065', '4008398120', 'Legendary', '5', null), ('1246793994', 'Maahes HC4', 'Hand Cannon', 'Roar with one voice. Rage against the storm.', '2465295065', '4008398120', 'Legendary', '5', null), ('1248372789', 'Sweet Sorrow', 'Auto Rifle', 'A scratched-out inscription on the barrel reads, "A birthday is just a number. How about we pick this one?"', '2465295065', '4008398120', 'Legendary', '5', null), ('1251729046', 'Steelfeather Repeater', 'Auto Rifle', 'There is strength in delicate things.', '1498876634', '4008398120', 'Legendary', '5', null), ('1253087083', 'IKELOS_SR_v1.0.2', 'Sniper Rifle', 'Subroutine IKELOS: Status=reinitiated.
APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('1258168956', 'Imminence', 'Submachine Gun', 'Untether expectation from reality.', '1498876634', '4008398120', 'Legendary', '5', null), ('1270948323', 'Nasreddin', 'Sword', 'This weapon was forged by Devrim Kay VIII for the survivors.', '953998645', '2395677314', 'Uncommon', '3', null), ('1271343896', 'Widow''s Bite', 'Sniper Rifle', 'I will outlive you.', '2465295065', '4008398120', 'Legendary', '5', null), ('1277015089', 'Gravity Slingshot', 'Shotgun', '"On the day our ships are ready, the City will see us blast into the sky." —Arach Jalaal', '2465295065', '4008398120', 'Legendary', '5', null), ('1280894514', 'Mechabre', 'Sniper Rifle', 'The killer robot killer.', '2465295065', '4008398120', 'Legendary', '5', null), ('1280933460', 'Claws of the Wolf', 'Pulse Rifle', '"Perun''s strikes would hit so fast and true that our enemies wouldn''t realize their fate until it was too late." —Lord Saladin', '2465295065', '4008398120', 'Legendary', '5', null), ('1281822856', 'Protostar CSu', 'Submachine Gun', 'What came before?', '1498876634', '2127292149', 'Rare', '4', null), ('1281822857', 'Philippis-B', 'Submachine Gun', 'You know these roads.', '1498876634', '2127292149', 'Rare', '4', null), ('1281822858', 'Furina-2mg', 'Submachine Gun', 'I am ready to defend my territory.', '2465295065', '2127292149', 'Rare', '4', null), ('1281822859', 'Harmony-21', 'Submachine Gun', 'SUROS reminds you that a fireteam is better than a soloist.', '2465295065', '2127292149', 'Rare', '4', null), ('1286686760', 'Gahlran''s Right Hand', 'Auto Rifle', '"A Reefborn autorifle, rewritten with Hive voices to defend Gahlran the failed. Now yours." —Emperor Calus', '1498876634', '4008398120', 'Legendary', '5', null), ('128782990', 'Fang of Ir Yût (Adept)', 'Scout Rifle', 'This is the shape and the point of the tooth: nothing has ever lived that will not die.', '1498876634', '4008398120', 'Legendary', '5', null), ('1288422452', 'Mos Athanor IV', 'Hand Cannon', 'Transform yourself.', '2465295065', '4008398120', 'Legendary', '5', null), ('1289000550', 'PLUG ONE.1', 'Fusion Rifle', 'Move with the current.', '2465295065', '4008398120', 'Legendary', '5', null), ('1289324202', 'Pyroclastic Flow', 'Rocket Launcher', 'There is no minimum safe distance.', '953998645', '4008398120', 'Legendary', '5', null), ('1289796511', 'Iterative Loop', 'Fusion Rifle', 'An antique from Neomuna''s founding, given new life.', '2465295065', '4008398120', 'Legendary', '5', null), ('1289997971', 'Breachlight', 'Sidearm', 'It has been melted and reforged many times.', '1498876634', '4008398120', 'Legendary', '5', null), ('1291586825', 'Eystein-D', 'Pulse Rifle', 'We guarantee a fair trial.', '1498876634', '4008398120', 'Legendary', '5', null), ('1292594730', 'The Summoner (Adept)', 'Auto Rifle', 'Join the dance of fire and birth.', '2465295065', '4008398120', 'Legendary', '5', null), ('1296429091', 'Deadpan Delivery', 'Shotgun', 'Emphasis on the "dead."', '2465295065', '4008398120', 'Legendary', '5', null), ('1298672084', 'Perfect Paradox', 'Shotgun', 'A tale that''s different from the rest: the thread unfurls against the clocks.
The one the Speaker loved the best must have a perfect paradox.', '1498876634', '4008398120', 'Legendary', '5', null), ('1298815317', 'Brigand''s Law', 'Sidearm', 'A glutton for punishment.', '2465295065', '4008398120', 'Legendary', '5', null), ('1303313141', 'Unsworn', 'Trace Rifle', '"No oath will bind me to the past." —Kerrev, the Erased', '1498876634', '4008398120', 'Legendary', '5', null), ('1310413524', 'Recital-17', 'Sidearm', 'SUROS reminds you that practice makes perfect.', '2465295065', '2395677314', 'Uncommon', '3', null), ('1310413525', 'Victoire SI2', 'Sidearm', 'Victory is a process, not a finality.', '2465295065', '2395677314', 'Uncommon', '3', null), ('1311684613', 'Dimensional Hypotrochoid', 'Grenade Launcher', '"What is this junk from, that old moon base? What do you mean, ''just refurbish it''?!" —Exodus Indigo Quartermaster', '953998645', '4008398120', 'Legendary', '5', null), ('1313528549', 'Sola''s Scar', 'Sword', 'Digging leaves a mark.', '953998645', '4008398120', 'Legendary', '5', null), ('1321506184', 'Qullim''s Terminus', 'Machine Gun', '"If only… if only we had heeded the queen…"', '953998645', '4008398120', 'Legendary', '5', null), ('1321626661', 'Eye of Sol (Adept)', 'Sniper Rifle', '"The sun took my sight; thus, the sun became my eyes." —Parables of the Allspring', '1498876634', '4008398120', 'Legendary', '5', null), ('1323862250', 'Riptide', 'Fusion Rifle', '"Sudden, swift, and deadly."', '1498876634', '4008398120', 'Legendary', '5', null), ('1325579289', 'Retrofuturist', 'Shotgun', 'They were so optimistic about us.', '2465295065', '4008398120', 'Legendary', '5', null), ('1327264046', 'Badlander', 'Shotgun', '"We are a long way from home." —Arrha (trans. from Eliksni)', '2465295065', '4008398120', 'Legendary', '5', null), ('1327432221', 'Perseverance', 'Auto Rifle', 'It was a long time coming. But it wasn''t the wait. It was the journey.', '2465295065', '4008398120', 'Legendary', '5', null), ('1331482397', 'MIDA Multi-Tool', 'Scout Rifle', 'Select application: Ballistic engagement. Entrenching tool. Avionics trawl. Troll smasher. Stellar sextant. List continues.', '1498876634', '2759499571', 'Exotic', '6', null), ('1331824604', 'Combined Action', 'Hand Cannon', 'Built with modular parts for fireteams out in the field.', '2465295065', '4008398120', 'Legendary', '5', null), ('1332123064', 'Wild Style', 'Grenade Launcher', '"War is an art." —Ikora', '2465295065', '4008398120', 'Legendary', '5', null), ('1337707096', 'Chrysura Melo', 'Auto Rifle', '"If you hear it, remove your helmet and face the closest Corsair. They will know what must be done." —Queen Mara', '2465295065', '4008398120', 'Legendary', '5', null), ('1339362514', 'Stochastic Variable', 'Submachine Gun', '"However certain we are of our simulations, they always contain an element of unpredictability." —Lakshmi-2', '2465295065', '4008398120', 'Legendary', '5', null), ('1342668638', 'Pleiades Corrector', 'Scout Rifle', '"No, I don''t think I''ll tell you what it''s for. That would be too easy." —Lakshmi-2', '2465295065', '4008398120', 'Legendary', '5', null), ('1345867570', 'Sweet Business', 'Auto Rifle', '"…I love my job."', '1498876634', '2759499571', 'Exotic', '6', null), ('1345867571', 'Coldheart', 'Trace Rifle', 'The latest Omolon engineering leverages liquid fuel as coolant to keep weapon systems at biting subzero temperatures.', '2465295065', '2759499571', 'Exotic', '6', null), ('1350102270', 'Niflheim Frost', 'Scout Rifle', 'The chill you feel is death.', '1498876634', '4008398120', 'Legendary', '5', null), ('135029084', 'Nessa''s Oblation', 'Shotgun', '"His influence doesn''t end at his Fourth Tomb. I will find the rest… by any means necessary." —Nessa, Acolyte of Nezarec', '2465295065', '4008398120', 'Legendary', '5', null), ('1351035691', 'Daedalus Code', 'Hand Cannon', 'Make your own escape.', '2465295065', '4008398120', 'Legendary', '5', null), ('1354727549', 'The Slammer (Adept)', 'Sword', 'The cutting edge.', '953998645', '4008398120', 'Legendary', '5', null), ('1357080535', 'Breath of the Dragon', 'Submachine Gun', '"Once Timur saw you, it was already over, whether they knew it or not." —Lord Saladin', '2465295065', '4008398120', 'Legendary', '5', null), ('135971347', 'Psi Aeterna IV', 'Pulse Rifle', 'Alone, unending, peerless.', '2465295065', '4008398120', 'Legendary', '5', null), ('1363238943', 'Ruinous Effigy', 'Trace Rifle', 'From the many wings of ruin blows a wind that will reshape this dead world.', '2465295065', '2759499571', 'Exotic', '6', null), ('1363886209', 'Gjallarhorn', 'Rocket Launcher', '“If there is beauty in destruction, why not also in its delivery?” — Feizel Crux', '953998645', '2759499571', 'Exotic', '6', null), ('1364093401', 'The Last Word', 'Hand Cannon', '"Yours, until the last flame dies and all words have been spoken." —Shin Malphur to you, as you journey forth into the unknown', '1498876634', '2759499571', 'Exotic', '6', null), ('136525518', 'Shining Sphere', 'Rocket Launcher', 'Above the cloud with its shadow is the star with its light.', '953998645', '4008398120', 'Legendary', '5', null), ('1366394399', 'Tears of Contrition', 'Scout Rifle', 'Message transmission successful // Message deleted without opening // Resend?', '1498876634', '4008398120', 'Legendary', '5', null), ('1366917989', 'Tomorrow''s Answer (Adept)', 'Rocket Launcher', 'Could you please repeat the question?', '953998645', '4008398120', 'Legendary', '5', null), ('1369487074', 'Orimund''s Anvil', 'Auto Rifle', '"He was the first to forge arms for the Iron Banner." —Lord Saladin', '1498876634', '4008398120', 'Legendary', '5', null), ('137879537', 'Curtain Call', 'Rocket Launcher', 'It''s time for the final bow.', '953998645', '4008398120', 'Legendary', '5', null), ('1386601612', 'Swift Ride XE8375', 'Pulse Rifle', 'A Black Armory experimental prototype.', '2465295065', '4008398120', 'Legendary', '5', null), ('1387987271', 'Silicon Neuroma (Adept)', 'Sniper Rifle', '"My future is concurrently irreversible and unknowable. Before it overtakes me, I desire a more abrupt end to those responsible." —Asher Mir', '1498876634', '4008398120', 'Legendary', '5', null), ('1389546626', 'Taraxippos', 'Scout Rifle', 'A flash of green on the event horizon.', '1498876634', '4008398120', 'Legendary', '5', null), ('1390080550', 'False Promises', 'Auto Rifle', 'Gripped in the hands of the desperate many.', '1498876634', '4008398120', 'Legendary', '5', null), ('1392429335', 'Broadsword Launcher', 'Rocket Launcher', 'Let our monarch''s spirit ring out and roar!', '953998645', '4008398120', 'Legendary', '5', null), ('1392919471', 'Trustee', 'Scout Rifle', 'A single word is etched inside the barrel: "Alton-1."', '2465295065', '4008398120', 'Legendary', '5', null), ('1393021133', 'Equinox Tsu', 'Fusion Rifle', 'When will balance be restored?', '2465295065', '2395677314', 'Uncommon', '3', null), ('1393021134', 'Nox Reve II', 'Fusion Rifle', 'In the dark of night we dream of the Light''s return.', '2465295065', '2395677314', 'Uncommon', '3', null), ('1393021135', 'Nox Calyx II', 'Fusion Rifle', 'Shed the husk of night and be reborn.', '2465295065', '2395677314', 'Uncommon', '3', null), ('1395261499', 'Xenophage', 'Machine Gun', 'This might sting a little.', '953998645', '2759499571', 'Exotic', '6', null), ('1399109800', 'Fel Taradiddle', 'Combat Bow', 'It''s an unassuming thing, but you''ll be amazed at the damage it can do when applied with precision.', '1498876634', '4008398120', 'Legendary', '5', null), ('1399243961', 'Reed''s Regret', 'Linear Fusion Rifle', '"Trust me." —Savathûn as Osiris', '953998645', '4008398120', 'Legendary', '5', null), ('1401300690', 'Eye of Sol', 'Sniper Rifle', '"The sun took my sight; thus, the sun became my eyes." —Parables of the Allspring', '1498876634', '4008398120', 'Legendary', '5', null), ('1402766122', 'Retrofuturist', 'Shotgun', 'They were so optimistic about us.', '2465295065', '4008398120', 'Legendary', '5', null), ('1402874079', 'Hawthorne''s Field-Forged Shotgun', 'Shotgun', '"What am I supposed to put here? ''It''s a gun. Kill bad guys with it.''" —Suraya Hawthorne', '1498876634', '4008398120', 'Legendary', '5', null), ('1403800851', 'Bite of the Fox', 'Sniper Rifle', '"Sometimes Skorri wouldn''t show herself until she was the only one left who could stand." —Lord Saladin', '1498876634', '4008398120', 'Legendary', '5', null), ('1406475890', 'Agamid', 'Hand Cannon', 'The lumbering beast stands ready to fight.', '1498876634', '4008398120', 'Legendary', '5', null), ('1411084669', 'Zenobia-D', 'Rocket Launcher', 'You are the true power on the throne.', '953998645', '4008398120', 'Legendary', '5', null), ('1411560894', 'Ahab Char', 'Auto Rifle', 'I''d strike the sun if it insulted me.', '2465295065', '4008398120', 'Legendary', '5', null), ('1419158093', 'M-17 "Fast Talker"', 'Submachine Gun', 'Imperium tech-based firearm common among syndicates vying for control in the Lawless Frontier.', '1498876634', '4008398120', 'Legendary', '5', null), ('14194600', 'Edge of Intent', 'Glaive', 'An echo of an ancient weapon, forged from a memory of cunning.', '2465295065', '2759499571', 'Exotic', '6', null), ('1432682459', 'Fang of Ir Yût', 'Scout Rifle', 'This is the shape and the point of the tooth: nothing has ever lived that will not die.', '1498876634', '4008398120', 'Legendary', '5', null), ('1435808083', 'Antedate', 'Submachine Gun', 'You can''t go back.', '2465295065', '4008398120', 'Legendary', '5', null), ('1441805468', 'The Navigator', 'Trace Rifle', 'I dive to understand.', '1498876634', '2759499571', 'Exotic', '6', null), ('1443049976', 'Interference VI', 'Grenade Launcher', 'Come between your enemies and their lives.', '953998645', '4008398120', 'Legendary', '5', null), ('1447836603', 'Subjunctive', 'Submachine Gun', 'Stop ''em? Pretty sure our deaths are just meant to be the early warning system.', '2465295065', '4008398120', 'Legendary', '5', null), ('1447973650', 'Rest for the Wicked', 'Sword', '