207', 'Revision Zero', 'Pulse Rifle', 'The first of many.', '1498876634', '2759499571', 'Exotic', '6', null), ('147444292', 'Omniscient Eye', 'Sniper Rifle', '"I have seen too much. No one else should bear these burdens." —Lisbon-13, Hunter of the Kentarch 3', '2465295065', '4008398120', 'Legendary', '5', null), ('1476654960', 'Judgment', 'Hand Cannon', '"The greatest threat to a Guardian is another Guardian." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('1478986057', 'Without Remorse', 'Shotgun', '"No regrets."', '2465295065', '4008398120', 'Legendary', '5', null), ('1481594633', 'Barrow-Dyad', 'Submachine Gun', 'Lay those unquiet thoughts to rest.', '1498876634', '2759499571', 'Exotic', '6', null), ('1481892490', 'The Palindrome (Adept)', 'Hand Cannon', 'Draw, O Coward!', '2465295065', '4008398120', 'Legendary', '5', null), ('1489452902', 'Courageous Surrender', 'Grenade Launcher', 'Do not go softly.', '953998645', '4008398120', 'Legendary', '5', null), ('1490571337', 'Future Safe 10', 'Sword', 'See who''s robed as if a god, who stands with pride above the rest!
Destroy this ancient nameless fraud! Destroy the one whose death was blessed!', '953998645', '4008398120', 'Legendary', '5', null), ('1491665733', 'Briar''s Contempt', 'Linear Fusion Rifle', '"You will never be rid of him." —Briar, Acolyte of Nezarec', '953998645', '4008398120', 'Legendary', '5', null), ('1492522228', 'Scintillation (Adept)', 'Linear Fusion Rifle', '"A paltry echo of the Ascendant Plane." —Toland, the Shattered', '953998645', '4008398120', 'Legendary', '5', null), ('14929251', 'Long Arm', 'Scout Rifle', 'Inescapable, from here to the Outer Rim.', '2465295065', '4008398120', 'Legendary', '5', null), ('1496419775', 'Bane of Sorrow', 'Machine Gun', '"A Reefborn heavy implement, rewritten with Hive voices to make way for Gahlran the failed. Now yours." —Emperor Calus', '953998645', '4008398120', 'Legendary', '5', null), ('1501688142', 'Doomed Petitioner', 'Linear Fusion Rifle', 'No more fear.', '953998645', '4008398120', 'Legendary', '5', null), ('1502662697', 'King Cobra-4fr', 'Linear Fusion Rifle', 'Only fools dare enter my kingdom.', '953998645', '2127292149', 'Rare', '4', null), ('1503609584', 'The Last Breath', 'Auto Rifle', '"All things end." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('1505862304', 'Claws of the Wolf', 'Pulse Rifle', '"Perun''s strikes would hit so fast and true that our enemies wouldn''t realize their fate until it was too late." —Lord Saladin', '2465295065', '4008398120', 'Legendary', '5', null), ('1506719573', 'Cold Front', 'Submachine Gun', 'Sweep in like a force of nature. Leave destruction in your wake.', '1498876634', '4008398120', 'Legendary', '5', null), ('1508896098', 'The Wardcliff Coil', 'Rocket Launcher', 'Ingenuity. Desperation. A haphazard prototype of terrible power. Such were the factors at play in the Wardcliff Incident.', '953998645', '2759499571', 'Exotic', '6', null), ('1509167284', 'Blood Feud', 'Submachine Gun', 'Thicker than water.', '1498876634', '4008398120', 'Legendary', '5', null), ('1513927136', 'Swift Ride', 'Pulse Rifle', 'It''ll be over before you know it.', '2465295065', '4008398120', 'Legendary', '5', null), ('1513927137', 'Disrespectful Stare', 'Pulse Rifle', 'Don''t you look at me that way!', '1498876634', '4008398120', 'Legendary', '5', null), ('1513927138', 'Lincoln Green', 'Pulse Rifle', 'The survivors of that day chose not to remember.', '1498876634', '4008398120', 'Legendary', '5', null), ('1513927139', 'Agenda 5', 'Pulse Rifle', 'Fifth time''s a charm.', '2465295065', '4008398120', 'Legendary', '5', null), ('1513993763', 'Friction Fire', 'Submachine Gun', 'Speed, heat, and Light. Fire away.', '1498876634', '4008398120', 'Legendary', '5', null), ('1518042134', 'Halfdan-D', 'Auto Rifle', 'Your name will ring out, your deeds will resound forever.', '1498876634', '4008398120', 'Legendary', '5', null), ('1518042135', 'Valakadyn', 'Auto Rifle', 'In dark water, my fangs are bared.', '2465295065', '4008398120', 'Legendary', '5', null), ('1523647826', 'Eternal Slumber', 'Pulse Rifle', '"The night sky closes in. We should not be here when the final star fades." —Arach Jalaal', '1498876634', '4008398120', 'Legendary', '5', null), ('1524387902', 'Seraphine Haze', 'Submachine Gun', 'A solemn reminder of a dizzying youth.', '1498876634', '4008398120', 'Legendary', '5', null), ('1526296434', 'Forensic Nightmare', 'Submachine Gun', 'We got a thousand bullets and only 999 casings. Find the odd one out.', '1498876634', '4008398120', 'Legendary', '5', null), ('1529450902', 'Mos Epoch III', 'Rocket Launcher', 'The perpetual eventually gives way to the variable.', '953998645', '4008398120', 'Legendary', '5', null), ('1531295694', 'Adverse Possession IX', 'Scout Rifle', 'Open and hostile and ready.', '2465295065', '4008398120', 'Legendary', '5', null), ('1532276803', 'Allied Demand', 'Sidearm', 'Rest satisfied with doing well, and leave others to talk of you as they please.', '1498876634', '4008398120', 'Legendary', '5', null), ('1533499360', 'Athelflad-D', 'Sidearm', 'Make yourself dreadful to your enemies and indispensable to your allies.', '1498876634', '4008398120', 'Legendary', '5', null), ('1533499361', 'Etana SI4', 'Sidearm', 'The reign of Light will be long and peaceful.', '2465295065', '4008398120', 'Legendary', '5', null), ('1533499362', 'Urchin-3si', 'Sidearm', 'I will draw them in, then take them out.', '2465295065', '4008398120', 'Legendary', '5', null), ('1536325168', 'Anamnesis (Adept)', 'Combat Bow', 'The Valence has dimmed, but the nature of the Echoes grows clearer.', '2465295065', '4008398120', 'Legendary', '5', null), ('153979396', 'Luna''s Howl', 'Hand Cannon', '"Guardians never die. But we don''t forget those who do." —Lord Shaxx', '2465295065', '4008398120', 'Legendary', '5', null), ('153979397', 'Better Devils', 'Hand Cannon', 'Angels can''t help you here.', '1498876634', '4008398120', 'Legendary', '5', null), ('153979399', 'Not Forgotten', 'Hand Cannon', '"Guardians never die. But we don''t forget those who do." —Lord Shaxx', '2465295065', '4008398120', 'Legendary', '5', null), ('1541131350', 'Cerberus+1', 'Auto Rifle', '"Because three heads are good, but four are better." —Jeza "Jeopardy" Verlayn', '1498876634', '2759499571', 'Exotic', '6', null), ('1552443158', 'Forgiveness', 'Sidearm', '"We all seek it, though few find it. The brave offer it, and humble learn from it. What am I?" —Dunya, Ghost of Aisha', '2465295065', '4008398120', 'Legendary', '5', null), ('1553681400', 'Opaque Hourglass', 'Combat Bow', 'Nobody knows how much time they have left.', '953998645', '4008398120', 'Legendary', '5', null), ('1555959830', 'Seventh Seraph Officer Revolver', 'Hand Cannon', 'A thing of elegance from a more civilized age.', '1498876634', '4008398120', 'Legendary', '5', null), ('1561006927', 'Seventh Seraph Carbine', 'Auto Rifle', 'The old workhorse, still with many years to give.', '1498876634', '4008398120', 'Legendary', '5', null), ('1572604081', 'Gizmo Weft', 'Grenade Launcher', 'Now what did this do again?', '1498876634', '4008398120', 'Legendary', '5', null), ('1572896086', 'Recurrent Impact', 'Machine Gun', 'It''s enough to drive someone out of their mind.', '953998645', '4008398120', 'Legendary', '5', null), ('1574601402', 'Whistler''s Whim', 'Combat Bow', 'The tune is the same, but the aim couldn''t be more different.', '1498876634', '4008398120', 'Legendary', '5', null), ('157601190', 'Joxer''s Longsword', 'Pulse Rifle', '"He bore it well." —Lord Shaxx', '2465295065', '4008398120', 'Legendary', '5', null), ('1584643826', 'Hush', 'Combat Bow', '"Breathe. Line up the shot. Enjoy the quiet before the kill." —The Drifter', '2465295065', '4008398120', 'Legendary', '5', null), ('1586231351', 'Mindbender''s Ambition', 'Shotgun', '"Hiraks always did like to leave an impression." —The Spider', '2465295065', '4008398120', 'Legendary', '5', null), ('1587439031', 'Three Graves', 'Pulse Rifle', '"No need to dig too deep. Our slumber will not be disturbed." —Arach Jalaal', '1498876634', '4008398120', 'Legendary', '5', null), ('1587779165', 'Radiant Stardust', 'Submachine Gun', '"We are but dust on a stellar wind." —Arach Jalaal', '2465295065', '4008398120', 'Legendary', '5', null), ('1587953057', 'Temptation''s Hook', 'Sword', 'A finger of death from which to hang.', '953998645', '4008398120', 'Legendary', '5', null), ('159056377', 'Requiem-45', 'Pulse Rifle', 'Requiem-45: SUROS invites you to honor the dead.', '2465295065', '4008398120', 'Legendary', '5', null), ('1594120904', 'No Time to Explain', 'Pulse Rifle', 'A single word etched onto the inside of the weapon''s casing: Now.', '1498876634', '2759499571', 'Exotic', '6', null), ('1595336070', 'Guseva-C', 'Hand Cannon', 'You know your purpose.', '1498876634', '2127292149', 'Rare', '4', null), ('1595336071', 'Presto-48', 'Hand Cannon', 'SUROS invites you to hold nothing back.', '2465295065', '2127292149', 'Rare', '4', null), ('1600633250', '21% Delirium', 'Machine Gun', '"All right." —A Dark Age