APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('1736135946', 'New Malpais', 'Pulse Rifle', '"Decide! Principles or power—you can''t have both." —Spider', '1498876634', '2759499571', 'Exotic', '6', null), ('174192097', 'CALUS Mini-Tool', 'Submachine Gun', 'An Earth artifact, refashioned to suit the Emperor''s modest tastes.', '2465295065', '4008398120', 'Legendary', '5', null), ('1744115122', 'Legend of Acrius', 'Shotgun', '"In the Cabal legend, a hero seeks to possess the sun. He succeeds. Then, he becomes Emperor. The Cabal… are not a subtle people." —Tyra Karn', '953998645', '2759499571', 'Exotic', '6', null), ('174804902', 'The Long Walk', 'Sniper Rifle', '"There is an end to everything." —Emissary of the Nine', '2465295065', '4008398120', 'Legendary', '5', null), ('1751893422', 'Disparity', 'Pulse Rifle', '"Identify yourself, or be destroyed." —Clovis Bray I', '1498876634', '4008398120', 'Legendary', '5', null), ('1752585070', 'BrayTech Winter Wolf', 'Auto Rifle', 'The leader of the pack endures through the harshest conditions.', '1498876634', '4008398120', 'Legendary', '5', null), ('1753923263', 'Wolfsbane', 'Sword', '"Nanites, Guardian." —Lord Saladin', '953998645', '2759499571', 'Exotic', '6', null), ('1757129747', 'Acantha-D XK8434', 'Grenade Launcher', 'A Black Armory experimental prototype.', '953998645', '4008398120', 'Legendary', '5', null), ('1757177186', 'Watchful Eye', 'Machine Gun', 'A Guardian is first watchful, that they might know right action.', '953998645', '4008398120', 'Legendary', '5', null), ('1757202961', 'Greasy Luck', 'Glaive', 'Death to the living, long life to the killers', '2465295065', '4008398120', 'Legendary', '5', null), ('1760543913', 'Legal Action II', 'Pulse Rifle', 'It''s time to file a complaint.', '1498876634', '4008398120', 'Legendary', '5', null), ('1762785662', 'VS Chill Inhibitor', 'Grenade Launcher', 'Research|EyesOnly|Castor|2142| Dr. Bray, I''m forwarding stationside casualty statistics. Can we talk?', '953998645', '4008398120', 'Legendary', '5', null), ('1762785663', 'VS Velocity Baton', 'Grenade Launcher', 'Archival|Pollux|Director|1421| From the office of Dr. Bray: Whoever''s supplying our plasteel is incompetent. One more chamber leak and I''ll sue. Get me a new contractor.', '2465295065', '4008398120', 'Legendary', '5', null), ('1763361847', 'Evening SI4', 'Sidearm', 'Night''s falling. Where are you?', '2465295065', '4008398120', 'Legendary', '5', null), ('1763584999', 'Grand Overture', 'Machine Gun', 'It''s not over until the vast red artificial intelligence sings.', '953998645', '2759499571', 'Exotic', '6', null), ('1764868900', 'Riiswalker', 'Shotgun', '"No. I will not allow a Fallen to fight in the Banner, that right is reserved for Guardians alone. But if you insist, I may allow a Guardian to carry a Fallen-forged weapon into battle. You are a weaponsmith, are you not?" —Lord Saladin to an Unknown Eliksni', '1498876634', '4008398120', 'Legendary', '5', null), ('1766088024', 'Thermal Erosion', 'Machine Gun', '"Europa has relit the fire in my soul; one that even its freezing winds cannot chill."  —Clovis Bray', '953998645', '4008398120', 'Legendary', '5', null), ('1769847435', 'A Distant Pull', 'Sniper Rifle', 'From distant hollows, a call demands attention.', '1498876634', '4008398120', 'Legendary', '5', null), ('1770490683', 'Non-Denouement', 'Combat Bow', 'This isn''t the end. Not yet.', '2465295065', '4008398120', 'Legendary', '5', null), ('1773600468', 'Critical Sass', 'Fusion Rifle', 'A chain reaction of nuclear insolence.', '2465295065', '4008398120', 'Legendary', '5', null), ('1773934241', 'Judgment', 'Hand Cannon', '"The greatest threat to a Guardian is another Guardian." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('177568179', 'Horror Story', 'Auto Rifle', 'It never starts out scary.', '1498876634', '4008398120', 'Legendary', '5', null), ('1775804198', 'Galliard-42 XN7568', 'Auto Rifle', 'A Black Armory experimental prototype.', '2465295065', '4008398120', 'Legendary', '5', null), ('1780464822', 'New Purpose', 'Pulse Rifle', 'I see you adorned in spots of blood like fallen rose petals. I see you victorious and bathed in light, I see you.', '1498876634', '4008398120', 'Legendary', '5', null), ('1786797708', 'Escape Velocity', 'Submachine Gun', '"The first step toward truth is to let go of all that we know and hold dear." —Arach Jalaal', '1498876634', '4008398120', 'Legendary', '5', null), ('1788603939', 'Herod-C', 'Auto Rifle', 'The Häkke Herod-C stays cool to the touch after hours of firing.', '1498876634', '4008398120', 'Legendary', '5', null), ('1789347249', 'Hazard of the Cast', 'Auto Rifle', '"Nothing for it once you place your life upon the die." —The Drifter', '1498876634', '4008398120', 'Legendary', '5', null), ('1796949035', 'Razor''s Edge', 'Sword', 'Not a soul would speak of what remained after that wretched blade found its marks.', '953998645', '4008398120', 'Legendary', '5', null), ('1798874854', '18 Kelvins', 'Sidearm', 'Cold-blooded.', '2465295065', '4008398120', 'Legendary', '5', null), ('1801007332', 'No Hesitation', 'Auto Rifle', '"He is the closest thing I will ever have to a son."', '2465295065', '4008398120', 'Legendary', '5', null), ('1802135586', 'Touch of Malice', 'Scout Rifle', '"Let them feel every lash, every curse, every touch of malice that they first dealt to me." —Eris Morn', '1498876634', '2759499571', 'Exotic', '6', null), ('1807343361', 'Hawthorne''s Field-Forged Shotgun', 'Shotgun', '"What am I supposed to put here? ''It''s a gun. Kill bad guys with it.''" —Suraya Hawthorne', '1498876634', '4008398120', 'Legendary', '5', null), ('1813474267', 'Arcane Embrace', 'Shotgun', 'Channel an aura of control over the energies of the universe.', '2465295065', '4008398120', 'Legendary', '5', null), ('1813667283', 'Dead-Ender', 'Linear Fusion Rifle', '"I question the wisdom of our current trajectory." —Arach Jalaal', '953998645', '4008398120', 'Legendary', '5', null), ('1815105249', 'Falling Guillotine', 'Sword', 'What won''t be given must be taken.', '953998645', '4008398120', 'Legendary', '5', null), ('1817605554', 'Cold Comfort (Adept)', 'Rocket Launcher', '"Do not be afraid."', '953998645', '4008398120', 'Legendary', '5', null), ('1820994983', 'The Summoner', 'Auto Rifle', 'Join the dance of fire and birth.', '2465295065', '4008398120', 'Legendary', '5', null), ('1821529912', 'Warden''s Law', 'Hand Cannon', 'Fight. Win. Li- Li- Li- Li- Li- FATAL EXCEPTION HAS OCCURRED AT 0028:C001E36', '1498876634', '4008398120', 'Legendary', '5', null), ('1821724780', 'Seventh Seraph CQC-12', 'Shotgun', 'Word into law, held at gunpoint.', '2465295065', '4008398120', 'Legendary', '5', null), ('1823308496', 'Synanceia', 'Sword', 'Don''t get too close.', '953998645', '4008398120', 'Legendary', '5', null), ('1824586582', 'Resounding', 'Fusion Rifle', 'Howl until the walls are alive with it.', '1498876634', '4008398120', 'Legendary', '5', null), ('1825472717', 'The End', 'Scout Rifle', '"Show them that safe harbor is very far away." —Emissary of the Nine', '2465295065', '4008398120', 'Legendary', '5', null), ('1827058652', 'Relentless (Adept)', 'Pulse Rifle', '"Embrace your fate." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('1833195496', 'Ager''s Scepter', 'Trace Rifle', '"One day, you will mold the world to your liking, dear brother, as I always have." —Queen Mara Sov', '1498876634', '2759499571', 'Exotic', '6', null), ('1834313033', 'Afterlight', 'Fusion Rifle', '"Best part of having been inside the Traveler? I''ve got an argument to win." —Peach the Ghost', '2465295065', '4008398120', 'Legendary', '5', null), ('1835747805', 'Nature of the Beast', 'Hand Cannon', 'Don''t let them change you.', '2465295065', '4008398120', 'Legendary', '5', null), ('1839565992', 'Ether Doctor', 'Auto Rifle', '"Control the supply." —The Spider', '1498876634', '4008398120', 'Legendary', '5', null), ('1842303080', 'Hollow Earth', 'Auto Rifle', '"Do we need another reminder? This world is but a grave." —Arach Jalaal', '2465295065', '4008398120', 'Legendary', '5', null), ('1843044398', 'Translation Theory', 'Sidearm', '"Must consider new ways… What cannot change, dies…" —Variks, the Loyal', '2465295065', '4008398120', 'Legendary', '5', null), ('1843044399', 'Smuggler''s Word', 'Sidearm', 'A deal is a deal. Or so you hope.', '1498876634', '4008398120', 'Legendary', '5', null), ('1845372864', 'Albedo Wing', 'Glaive', 'From this high up, the sunlight on snow looks like fire.', '2465295065', '4008398120', 'Legendary', '5', null), ('1845978721', 'Avalanche', 'Machine Gun', 'If they''re close enough to see it start, then they''d better run.', '953998645', '4008398120', 'Legendary', '5', null), ('1851521408', 'Jararaca-3sr', 'Scout Rifle', 'I slither, I strike.', '1498876634', '4008398120', 'Legendary', '5', null), ('1851777734', 'Apex Predator', 'Rocket Launcher', 'Is it you or I that tops the food chain, o challenger mine?', '953998645', '4008398120', 'Legendary', '5', null), ('1852863732', 'Wavesplitter', 'Trace Rifle', 'Omolon''s newest breakthrough uses focused sonic waves to superheat electrons into a devastating energy beam.', '2465295065', '2759499571', 'Exotic', '6', null), ('1853180924', 'Traveler''s Chosen', 'Sidearm', '"All we have left now is our faith."', '1498876634', '2759499571', 'Exotic', '6', null), ('1854753404', 'Wendigo GL3', 'Grenade Launcher', 'Turn your hunger outward, never inward.', '953998645', '4008398120', 'Legendary', '5', null), ('1854753405', 'The Militia''s Birthright', 'Grenade Launcher', '"Earth is our home. Not Mars, not Venus, not even the Reef. We must ensure it is a place we can continue to live for many generations to come." —Devrim Kay', '1498876634', '4008398120', 'Legendary', '5', null), ('1856262127', 'Something New', 'Hand Cannon', '"It''s new to me." —Banshee-44', '1498876634', '4008398120', 'Legendary', '5', null), ('186