6', 'Hezen Vengeance (Timelost)', 'Rocket Launcher', 'The Hezen Axis Mind is tireless and infinite. Tireless and infinite. Tireless and infinite…', '953998645', '4008398120', 'Legendary', '5', null), ('1924276978', 'Horror''s Least (Adept)', 'Pulse Rifle', '"Some things should not be saved." —Techeun Sedia', '2465295065', '4008398120', 'Legendary', '5', null), ('1927800278', 'Eternal Blazon', 'Scout Rifle', '"But this eternal blazon must not be to ears of flesh and blood."', '2465295065', '4008398120', 'Legendary', '5', null), ('192784503', 'Pre Astyanax IV', 'Combat Bow', 'The lord of the city grants the blessing of precision.', '2465295065', '4008398120', 'Legendary', '5', null), ('1929278169', 'BrayTech Osprey', 'Rocket Launcher', 'Expected Use Timeframe: UNKNOWN.', '953998645', '4008398120', 'Legendary', '5', null), ('1931556011', 'No Feelings', 'Scout Rifle', 'Lose yourself in the moment.', '2465295065', '4008398120', 'Legendary', '5', null), ('1937552980', 'Doom of Chelchis', 'Scout Rifle', '"Where is the Great Machine? Where is the Great Machine?" —Chelchis, Kell of Stone', '2465295065', '4008398120', 'Legendary', '5', null), ('1940885628', 'Archimedes Truth', 'Sniper Rifle', 'The shortest distance between two points is a straight line.', '2465295065', '4008398120', 'Legendary', '5', null), ('1941816543', 'Submission (Adept)', 'Submachine Gun', 'Shape: Devotion', '1498876634', '4008398120', 'Legendary', '5', null), ('1942069133', 'Dark Decider', 'Auto Rifle', 'The oldest, shortest words—yes and no—are those which require the most thought.', '2465295065', '4008398120', 'Legendary', '5', null), ('1946491241', 'Truthteller', 'Grenade Launcher', '"If we wish others to accept the grim reality, we must break through every comforting illusion." —Arach Jalaal', '2465295065', '4008398120', 'Legendary', '5', null), ('1948035256', 'Luna Regolith III', 'Sniper Rifle', 'Shed the brittle facade to reveal molten wrath.', '2465295065', '4008398120', 'Legendary', '5', null), 