Above the dead and yet-to-die, a legion''s blade with fire screams.', '2465295065', '4008398120', 'Legendary', '5', null), ('20935540', 'Arctic Haze', 'Auto Rifle', '"A haze permeates the air here, occluding clear sight. Be very sure of your aim." —The Exo Stranger', '2465295065', '4008398120', 'Legendary', '5', null), ('2094938673', 'Adjudicator', 'Submachine Gun', '"Hesitation kills." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('2097055732', 'Piece of Mind', 'Pulse Rifle', 'With words or weapons, inaccuracy can be fatal.', '1498876634', '4008398120', 'Legendary', '5', null), ('2099894368', 'Battle Scar', 'Pulse Rifle', '"Do not concern yourself with how many horns I bear." —Lord Shaxx', '1498876634', '4008398120', 'Legendary', '5', null), ('210065223', 'Magnum Shepherd', 'Pulse Rifle', 'Bring magnificent and glorious battle.', '1498876634', '4008398120', 'Legendary', '5', null), ('2105827099', 'Bad Reputation', 'Submachine Gun', '"Here we can start over." —Mithrax, trans. from Eliksni', '2465295065', '4008398120', 'Legendary', '5', null), ('2108920981', 'Orewing''s Maul', 'Grenade Launcher', '"They were the first to chart the Cosmodrome''s mountains." —Lord Saladin', '2465295065', '4008398120', 'Legendary', '5', null), ('2111625436', 'Aurora Dawn', 'Sword', '"The prospect of a future is something we have to keep in mind."', '953998645', '4008398120', 'Legendary', '5', null), ('2112909414', 'Duke Mk. 44', 'Hand Cannon', 'Slow to shoot, but brutal upon impact.', '1498876634', '4008398120', 'Legendary', '5', null), ('2112909415', 'Ten Paces', 'Hand Cannon', 'Better be quick.', '1498876634', '4008398120', 'Legendary', '5', null), ('211732170', 'Hammerhead', 'Machine Gun', 'Smash through the veil.', '953998645', '4008398120', 'Legendary', '5', null), ('2119346509', 'Ammit AR2', 'Auto Rifle', 'Dying edge dual-chamber stabilization matrix technology makes this the most balanced Auto Rifle that Omolon has ever produced.', '2465295065', '4008398120', 'Legendary', '5', null), ('211938782', 'Whispering Slab', 'Combat Bow', 'It sings of sorrows that have not yet come to pass.', '1498876634', '4008398120', 'Legendary', '5', null), ('2121785039', 'Brass Attacks', 'Sidearm', '"If looks could kill, you wouldn''t even have to aim this thing." —Banshee-44', '2465295065', '4008398120', 'Legendary', '5', null), ('2126178511', 'Corrasion', 'Pulse Rifle', 'Watch your step.', '2465295065', '4008398120', 'Legendary', '5', null), ('2126543269', 'Cold Comfort (Adept)', 'Rocket Launcher', '"Do not be afraid."', '953998645', '4008398120', 'Legendary', '5', null), ('2129814338', 'Prosecutor', 'Auto Rifle', '"All this in service of one purpose. You have their attention. Let us see if you can keep it." —Emissary of the Nine', '2465295065', '4008398120', 'Legendary', '5', null), ('2130065553', 'Arbalest', 'Linear Fusion Rifle', '"We didn''t have linear fusions in the Dark Age. But we made it work." —The Drifter', '1498876634', '2759499571', 'Exotic', '6', null), ('2130875369', 'Sojourner''s Tale', 'Shotgun', 'Home is just over the horizon.', '2465295065', '4008398120', 'Legendary', '5', null), ('213264394', 'Buzzard', 'Sidearm', 'Circle ''round, great harbinger of death.', '1498876634', '4008398120', 'Legendary', '5', null), ('2138599001', 'Optative', 'Hand Cannon', 'If only you could see yourself. But you have no eyes. Not the dimmest sense survives…', '2465295065', '4008398120', 'Legendary', '5', null), ('2139640995', 'Hero of Ages', 'Sword', 'After every age of darkness, an age of light.', '953998645', '4008398120', 'Legendary', '5', null), ('2140635451', 'Sleepless', 'Rocket Launcher', '"I see our path ahead, full of despair and hardship, and I will walk it with joy in my heart." —Sjur Eido', '953998645', '4008398120', 'Legendary', '5', null), ('2145441168', 'Prophet of Doom', 'Shotgun', '"You know how this will end." —Yardarm-4, Titan of the Kentarch 3', '2465295065', '4008398120', 'Legendary', '5', null), ('2145476620', 'Bad News', 'Hand Cannon', 'Sit down. We need to talk.', '1498876634', '4008398120', 'Legendary', '5', null), ('2145476622', 'Shattered Peace', 'Hand Cannon', 'Only you can make it whole again.', '2465295065', '4008398120', 'Legendary', '5', null), ('2145476623', 'Annual Skate', 'Hand Cannon', '"When the lake used to freeze, people would dance on the ice wearing boots with tiny swords. And fall in love."', '2465295065', '4008398120', 'Legendary', '5', null), ('2147010335', 'Shadow Price (Adept)', 'Auto Rifle', 'A precision Auto Rifle left behind by Toland, the Shattered. It asks so little, and it offers so much.', '2465295065', '4008398120', 'Legendary', '5', null), ('2149166938', 'Classical-42', 'Rocket Launcher', 'SUROS invites you to bring back the classics.', '953998645', '4008398120', 'Legendary', '5', null), ('2149166939', 'Countess SA/2', 'Rocket Launcher', 'A noble commander of the battlefield.', '953998645', '4008398120', 'Legendary', '5', null), ('2149683300', 'IKELOS_SMG_v1.0.3', 'Submachine Gun', 'Subroutine IKELOS: Status=reinitiated.
