last.', '1498876634', '2395677314', 'Uncommon', '3', null), ('2213848861', 'Cadenza-11', 'Pulse Rifle', 'A modded version of the Cadenza-43, a Guardian standby.', '2465295065', '2395677314', 'Uncommon', '3', null), ('2213848862', 'Standing Tall', 'Pulse Rifle', 'Hawthorne forged this weapon out of scraps and salvage during her years alone in the wilds.', '1498876634', '2395677314', 'Uncommon', '3', null), ('2213848863', 'Psi Ferox II', 'Pulse Rifle', 'Fury is an energy, too.', '1498876634', '2395677314', 'Uncommon', '3', null), ('2217366863', 'Parcel of Stardust', 'Shotgun', 'Everybody''s looking for theirs.', '1498876634', '4008398120', 'Legendary', '5', null), ('2218569744', 'Tarnished Mettle', 'Scout Rifle', 'Survival is the better part of valor.', '2465295065', '4008398120', 'Legendary', '5', null), ('2220884262', 'The Steady Hand', 'Hand Cannon', 'Forged in honor of Perun, and a just and unwavering resolve.', '1498876634', '4008398120', 'Legendary', '5', null), ('2221264583', 'Smite of Merain', 'Pulse Rifle', '"No tomb but the battlefield! No legacy but the scars we etch upon our foes!"', '1498876634', '4008398120', 'Legendary', '5', null), ('2222560548', 'IKELOS_SMG_v1.0.2', 'Submachine Gun', 'Subroutine IKELOS: Status=reinitiated.
APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('222606050', 'Glissando-47', 'Scout Rifle', 'SUROS invites you to glide along.', '1498876634', '4008398120', 'Legendary', '5', null), ('2226158470', 'Unworthy', 'Scout Rifle', '"Deity turned three eyes from me." —Ir Kithana, Preceptor', '2465295065', '4008398120', 'Legendary', '5', null), ('2226572694', 'Judgment', 'Hand Cannon', '"The greatest threat to a Guardian is another Guardian." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('2228325504', 'Edge Transit', 'Grenade Launcher', 'What did you trade away to secure passage to the edge?', '953998645', '4008398120', 'Legendary', '5', null), ('2231910050', 'Roar of the Bear', 'Rocket Launcher', '"Silimar''s defense broke more assaults than not. His retribution would shake the ground." —Lord Saladin', '953998645', '4008398120', 'Legendary', '5', null), ('2232171099', 'Deathbringer', 'Rocket Launcher', '"Sing them a lullaby of death and nothing more."', '953998645', '2759499571', 'Exotic', '6', null), ('2233545123', 'Fugue-55', 'Sniper Rifle', 'SUROS invites you to follow our lead.', '2465295065', '4008398120', 'Legendary', '5', null), ('2241507890', 'Sacred Provenance', 'Pulse Rifle', '"These gifts were not made for us, but we were meant to have them." —Rekkana, Warlock of the Kentarch 3', '1498876634', '4008398120', 'Legendary', '5', null), ('2246386812', 'The Heron', 'Glaive', 'Strike from calm waters.', '2465295065', '4008398120', 'Legendary', '5', null), ('2248667690', 'Perfect Paradox', 'Shotgun', 'A tale that''s different from the rest: the thread unfurls against the clocks.
