egendary', '5', null), ('2276328320', 'Veles-X', 'Pulse Rifle', 'Control the flanks and the battle is yours.', '2465295065', '4008398120', 'Legendary', '5', null), ('2278995296', 'Does Not Compute', 'Scout Rifle', 'The engineers aren''t ready for us.', '1498876634', '4008398120', 'Legendary', '5', null), ('228424224', 'Impromptu-49', 'Pulse Rifle', 'SUROS invites you to be spontaneous.', '2465295065', '4008398120', 'Legendary', '5', null), ('2286143274', 'The Huckleberry', 'Submachine Gun', 'Nothin'' in the world that 30 rounds can''t solve.', '1498876634', '2759499571', 'Exotic', '6', null), ('2290416', 'The Wizened Rebuke', 'Fusion Rifle', 'Forged in honor of Skorri, of lessons learned and lessons taught.', '2465295065', '4008398120', 'Legendary', '5', null), ('2290863050', 'Persuader', 'Sniper Rifle', '"They say you can''t reason with these enemies. I dunno—my gun and I seem to manage just fine." —Kei-Ying', '2465295065', '4008398120', 'Legendary', '5', null), ('2291392465', 'Anamnesis', 'Combat Bow', 'The Valence has dimmed, but the nature of the Echoes grows clearer.', '2465295065', '4008398120', 'Legendary', '5', null), ('2295941920', 'Belfry Bounty', 'Sniper Rifle', '"Making guns helps the hours pass. Especially since Suraya never calls…" —Devrim Kay', '2465295065', '4008398120', 'Legendary', '5', null), ('2295941921', 'Maestro-46', 'Sniper Rifle', 'SUROS invites you to lead.', '2465295065', '4008398120', 'Legendary', '5', null), ('2297554989', 'Riptide', 'Fusion Rifle', '"Sudden, swift, and deadly."', '1498876634', '4008398120', 'Legendary', '5', null), ('2298039571', 'Rake Angle', 'Glaive', 'Sharpness is a product of both tool and wielder.', '1498876634', '4008398120', 'Legendary', '5', null), ('2300143112', 'Yesterday''s Question', 'Hand Cannon', 'You already know the answer.', '2465295065', '4008398120', 'Legendary', '5', null), ('2302346155', 'IKELOS_SR_v1.0.3', 'Sniper Rifle', 'Subroutine IKELOS: Status=reinitiated.
APOTHEOSIS: Status=active…', '2465295065', '4008398120', 'Legendary', '5', null), ('2306182339', 'Wilderflight', 'Grenade Launcher', 'The flightless blind, venturing out into the dark. Never to return.', '2465295065', '4008398120', 'Legendary', '5', null), ('2307365', 'The Inquisitor (Adept)', 'Shotgun', 'Ask the question.', '2465295065', '4008398120', 'Legendary', '5', null), ('231031173', 'Mykel''s Reverence', 'Sidearm', '"Pain… Fear… Sacrifice… Feed the fiend." —Mykel, Leader of the Acolytes of Nezarec', '1498876634', '4008398120', 'Legendary', '5', null), ('2313726158', 'Belisarius-D', 'Pulse Rifle', 'Blinded by victory, you have forgotten the lessons of defeat.', '1498876634', '4008398120', 'Legendary', '5', null), ('2314610827', 'Igneous Hammer (Adept)', 'Hand Cannon', 'Forged by fire and might.', '2465295065', '4008398120', 'Legendary', '5', null), ('2314999489', 'Imperative', 'Scout Rifle', '"We must stop the weavers before they seal the Garden and begin to summon back its heart." —Ikora Rey', '1498876634', '4008398120', 'Legendary', '5', null), ('2316331767', 'Permafrost', 'Grenade Launcher', 'Freeze them out.', '1498876634', '4008398120', 'Legendary', '5', null), ('2322926844', 'Shadow Price', 'Auto Rifle', 'A precision Auto Rifle left behind by Toland, the Shattered. It asks so little, and it offers so much.', '2465295065', '4008398120', 'Legendary', '5', null), ('2323544076', 'Hollow Denial', 'Trace Rifle', '"Never forget what is taken from you."', '2465295065', '4008398120', 'Legendary', '5', null), ('2326578623', 'Fortunate Star', 'Combat Bow', 'When it shines at dusk, luck will surely come your way.', '2465295065', '4008398120', 'Legendary', '5', null), ('2326716489', 'Gunnora''s Axe', 'Shotgun', '"She taught us all to appreciate a good, sturdy axe." —Lord Saladin', '2465295065', '4008398120', 'Legendary', '5', null), ('2328531378', 'Lodbrok-C', 'Auto Rifle', 'My progeny will avenge me.', '1498876634', '4008398120', 'Legendary', '5', null), ('2328923181', 'Breachlight', 'Sidearm', 'It has been melted and reforged many times.', '1498876634', '4008398120', 'Legendary', '5', null), ('232928045', 'Under Your Skin', 'Combat Bow', 'The splinter you just can''t remove.', '2465295065', '4008398120', 'Legendary', '5', null), ('2330860573', 'The Inquisitor (Adept)', 'Shotgun', 'Ask the question.', '2465295065', '4008398120', 'Legendary', '5', null), ('233402416', 'New Pacific Epitaph (Adept)', 'Grenade Launcher', '"This isn''t happening. This isn''t happening. This isn''t happening."', '1498876634', '4008398120', 'Legendary', '5', null), ('233423981', 'Warden''s Law', 'Hand Cannon', 'Fight. Win. Li- Li- Li- Li- Li- FATAL EXCEPTION HAS OCCURRED AT 0028:C001E36', '1498876634', '4008398120', 'Legendary', '5', null), ('2334480463', 'Corrective Measure (Timelost)', 'Machine Gun', 'A full measure annihilates the rules of reality.', '953998645', '4008398120', 'Legendary', '5', null), ('233635202', 'Cruel Mercy', 'Pulse Rifle', 'Sometimes it''s kinder to let go.', '2465295065', '4008398120', 'Legendary', '5', null), ('2338088853', 'Calusea Noblesse', 'Scout Rifle', '"A Reefborn long rifle, rewritten with Hive voices to arm Gahlran the failed. Now yours." —Emperor Calus', '2465295065', '4008398120', 'Legendary', '5', null), ('233896077', 'Compass Rose', 'Shotgun', '"Let the Light be your compass." —Mithrax', '2465295065', '4008398120', 'Legendary', '5', null), ('2342054803', 'Ogma PR6', 'Pulse Rifle', 'All that power just jumps out of your hands. Hold on tight.', '2465295065', '4008398120', 'Legendary', '5', null), ('2344383760', 'Eighty-Six', 'Sword', 'Get rid of it.', '953998645', '4008398120', 'Legendary', '5', null), ('2345794502', 'Forgiveness', 'Sidearm', '"We all seek it, though few find it. The brave offer it, and humble learn from it. What am I?" —Dunya, Ghost of Aisha', '2465295065', '4008398120', 'Legendary', '5', null), ('2347178967', 'Cruel Mercy (Adept)', 'Pulse Rifle', 'Sometimes it''s kinder to let go.', '2465295065', '4008398120', 'Legendary', '5', null), ('2349907931', 'Prolonged Engagement', 'Submachine Gun', 'Fight until the bitter end.', '1498876634', '4008398120', 'Legendary', '5', null), ('2350330520', 'Sightline Survey', 'Hand Cannon', '"Picking up a lot of Fallen chatter. And Cabal chatter. And Fallen-Cabal chatter. If I ever got beauty sleep, I would say they are interrupting it!" —Failsafe', '2465295065', '4008398120', 'Legendary', '5', null), ('2350354266', 'Alethonym', 'Grenade Launcher', 'I know your name.', '1498876634', '2759499571', 'Exotic', '6', null), ('2351180975', 'Igneous Hammer', 'Hand Cannon', 'Forged by fire and might.', '2465295065', '4008398120', 'Legendary', '5', null), ('2351747816', 'Cuboid ARu', 'Auto Rifle', 'What is the shape of reality?', '1498876634', '2127292149', 'Rare', '4', null), ('2351747817', 'Refrain-23', 'Auto Rifle', 'SUROS invites you to do it again.', '2465295065', '2127292149', 'Rare', '4', null), ('2351747818', 'Sand Wasp-3au', 'Auto Rifle', 'Watch as I destroy you.', '2465295065', '2127292149', 'Rare', '4', null), ('2351747819', 'Ros Lysis II', 'Auto Rifle', 'Here is a way to free your enemies from their earthly tethers.', '1498876634', '2127292149', 'Rare', '4', null), ('2357297366', 'Witherhoard', 'Grenade Launcher', '"Like a one-man private security company." —The Drifter', '1498876634', '2759499571', 'Exotic', '6', null), ('235827225', 'Eyasluna', 'Hand Cannon', 'One day, young hawk, thou shalt sail beneath the silvered moon.', '1498876634', '4008398120', 'Legendary', '5', null), ('2362471600', 'Drang', 'Sidearm', 'Since the Collapse, these pistols have been retooled several times to boost their firepower. A worn inscription reads, "To Victor, from Sigrun."', '2465295065', '4008398120', 'Legendary', '5', null), ('2362471601', 'Rat King', 'Sidearm', 'We are small, but we are legion.', '1498876634', '2759499571', 'Exotic', '6', null), ('2362652544', 'Praedyth''s Revenge (Timelost)', 'Sniper Rifle', 'Praedyth will never fall.', '1498876634', '4008398120', 'Legendary', '5', null), ('2370525224', 'Reghusk''s Pledge', 'Auto Rifle', 'Forged by the Iron War Beasts in honor of their Valus.', '2465295065', '4008398120', 'Legendary', '5', null), ('2372514508', 'Blast Furnace', 'Pulse Rifle', 'Forged in the hottest fires.', '1498876634', '4008398120', 'Legendary', '5', null), ('2372514509', 'Elsie''s Rifle', 'Pulse Rifle', 'The future is built by many hands.', '2465295065', '4008398120', 'Legendary', '5', null), ('2376481550', 'Anarchy', 'Grenade Launcher', '"Stick to wall, ground, human… then FFFFFRRRRRYYYYY! Hehehehehehehe." —Siviks, Lost to None', '953998645', '2759499571', 'Exotic', '6', null), ('2378101424', 'The Militia''s Birthright (Adept)', 'Grenade Launcher', '"Earth is our home. Not Mars, not Venus, not even the Reef. We must ensure it is a place we can continue to live for many generations to come." —Devrim Kay', '1498876634', '4008398120', 'Legendary', '5', null), ('2378785953', 'Yesterday''s Question (Adept)', 'Hand Cannon', 'You already know the answer.', '2465295065', '4008398120', 'Legendary', '5', null), ('2386979999', 'The Scholar (Adept)', 'Scout Rifle', 'You can''t pull an all-nighter when the sun never sets.', '1498876634', '4008398120', 'Legendary', '5', null), ('2398848320', 'Erentil FR4', 'Fusion Rifle', 'Bring on the sunrise.', '2465295065', '4008398120', 'Legendary', '5', null), ('2399110176', 'Eyes of Tomorrow', 'Rocket Launcher', '"I want to see it all, unhindered, and know it''s mine to take." —Clovis Bray', '953998645', '2759499571', 'Exotic', '6', null), ('2405619467', 'Forgiveness (Adept)', 'Sidearm', '"We all seek it, though few find it. The brave offer it, and humble learn from it. What am I?" —Dunya, Ghost of Aisha', '2465295065', '4008398120', 'Legendary', '5', null), ('2408405461', 'Sacred Provenance', 'Pulse Rifle', '"These gifts were not made for us, but we were meant to have them." —Rekkana, Warlock of the Kentarch 3', '1498876634', '4008398120', 'Legendary', '5', null), ('2414141462', 'The Vision', 'Sidearm', 'Glory in the damage the right blast can do.', '2465295065', '4008398120', 'Legendary', '5', null), ('2414612776', 'New City', 'Submachine Gun', '"That''s what I see when I look at the Farm." —Devrim Kay', '1498876634', '4008398120', 'Legendary', '5', null), ('2414612777', 'Atalanta-D', 'Submachine Gun', 'They will tell you that you can''t. Don''t listen to them.', '1498876634', '4008398120', 'Legendary', '5', null), ('2415517654', 'Bastion', 'Fusion Rifle', '"The final stand is wherever I plant my feet. Not one step more." —Saint-14', '1498876634', '2759499571', 'Exotic', '6', null), ('2421180981', 'Incisor (Adept)', 'Trace Rifle', 'An infinitely sharp edge to dissect reality.', '1498876634', '4008398120', 'Legendary', '5', null), ('2422664927', 'Atalanta-D XG1992', 'Submachine Gun', 'A Black Armory experimental prototype.', '1498876634', '4008398120', 'Legendary', '5', null), ('2423071981', 'Lionfish-4fr', 'Fusion Rifle', 'Bright color is your first and final warning.', '1498876634', '4008398120', 'Legendary', '5', null), ('2429822976', 'Rose', 'Hand Cannon', 'In his strong hand the man held a Rose. And his aura burned bright.', '1498876634', '4008398120', 'Legendary', '5', null), ('2429822977', 'Austringer', 'Hand Cannon', 'An Earth artifact, refashioned to suit the Emperor''s modest tastes.', '1498876634', '4008398120', 'Legendary', '5', null), ('2433826056', 'The Quickstep', 'Submachine Gun', 'SUROS invites you pick up the pace.', '2465295065', '4008398120', 'Legendary', '5', null), ('2434225986', 'Shattered Cipher', 'Machine Gun', 'All doors open before you.', '953998645', '4008398120', 'Legendary', '5', null), ('243425374', 'Falling Guillotine', 'Sword', 'What won''t be given must be taken.', '953998645', '4008398120', 'Legendary', '5', null), ('2443900757', 'The Comedian (Adept)', 'Shotgun', 'A. A ha. A ha ha ha. A ha ha ha ha ha ha ha.', '2465295065', '4008398120', 'Legendary', '5', null), ('2448907086', 'Royal Entry', 'Rocket Launcher', 'You have arrived.', '953998645', '4008398120', 'Legendary', '5', null), ('2450049485', 'Line in the Sand', 'Linear Fusion Rifle', 'No farther.', '953998645', '4008398120', 'Legendary', '5', null), ('2450917538', 'Uzume RR4', 'Sniper Rifle', 'With the Uzume RR4 on your side, the Darkness doesn''t stand a chance.', '2465295065', '4008398120', 'Legendary', '5', null), ('2453357042', 'Blast Battue', 'Grenade Launcher', '"Yes, you got the kill, but the pelt is ruined." —Devrim Kay', '953998645', '4008398120', 'Legendary', '5', null), ('2462965802', 'Uncivil Discourse', 'Hand Cannon', '"Barant Imperium came up outta nowhere—and they brought new energy tech with''em. I kitbashed this beauty ''outta their goods." —The Drifter', '2465295065', '4008398120', 'Legendary', '5', null), ('2465372924', 'Tigerspite', 'Auto Rifle', '"What else can we do but take up arms?" —Corsair Amrita Vae', '1498876634', '4008398120', 'Legendary', '5', null), ('2475355656', 'Reed''s Regret (Adept)', 'Linear Fusion Rifle', '"Trust me." —Savathûn as Osiris', '953998645', '4008398120', 'Legendary', '5', null), ('2477408004', 'Wilderflight (Adept)', 'Grenade Launcher', 'The flightless blind, venturing out into the dark. Never to return.', '2465295065', '4008398120', 'Legendary', '5', null), ('2477980485', 'Mechabre', 'Sniper Rifle', 'The killer robot killer.', '2465295065', '4008398120', 'Legendary', '5', null), ('2478247171', 'Quitclaim Shotgun III', 'Shotgun', 'Ownership rules.', '2465295065', '4008398120', 'Legendary', '5', null), ('2478792241', 'The Scholar', 'Scout Rifle', 'You can''t pull an all-nighter when the sun never sets.', '1498876634', '4008398120', 'Legendary', '5', null), ('2480074702', 'Forbearance', 'Grenade Launcher', 'Shape: Temperance', '2465295065', '4008398120', 'Legendary', '5', null), ('2481758391', 'Darkest Before', 'Pulse Rifle', '"Persevere, or die in darkness. The choice is yours." —Emissary of the Nine', '2465295065', '4008398120', 'Legendary', '5', null), ('2481881293', 'Cartesian Coordinate', 'Fusion Rifle', 'Where does one end and the other begin?', '2465295065', '4008398120', 'Legendary', '5', null), ('2485881870', 'Unloved', 'Hand Cannon', '"Better alone than in unwanted company." —Jjenr, Husk', '1498876634', '4008398120', 'Legendary', '5', null), ('2488587246', 'The Hero''s Burden', 'Submachine Gun', 'Forged in honor of Saladin, of all that has been lost and all that remains.', '2465295065', '4008398120', 'Legendary', '5', null), ('2490988246', 'CALUS Mini-Tool', 'Submachine Gun', 'An Earth artifact, refashioned to suit the Emperor''s modest tastes.', '2465295065', '4008398120', 'Legendary', '5', null), ('2492081469', 'The Number', 'Auto Rifle', '"Ah, but which number? Why it and no others?" —Lakshmi-2', '2465295065', '4008398120', 'Legendary', '5', null), ('2496242052', 'Code Duello', 'Rocket Launcher', 'An unfinished inscription runs along the barrel: "Tlamus, she who—"', '953998645', '4008398120', 'Legendary', '5', null), ('2496875173', 'Sorrow''s Verse', 'Auto Rifle', 'Nothing resonates like grief.', '2465295065', '4008398120', 'Legendary', '5', null), ('2499720827', 'Midnight Coup', 'Hand Cannon', 'The conspirators were too afraid to kill me—rightly so. I am the beloved father of the people, and the glorious mob would not suffer my death. My sentence was exile.', '1498876634', '4008398120', 'Legendary', '5', null), ('2501377328', 'Division (Adept)', 'Sidearm', 'An enneagram tips, poised to shatter.', '2465295065', '4008398120', 'Legendary', '5', null), ('2502422772', 'Cartesian Coordinate', 'Fusion Rifle', 'Where does one end and the other begin?', '2465295065', '4008398120', 'Legendary', '5', null), ('2502422773', 'Shock and Awe', 'Fusion Rifle', 'Do not fear. Be what others fear.', '2465295065', '4008398120', 'Legendary', '5', null), ('2502422774', 'Nox Echo III', 'Fusion Rifle', 'Listen, and you will hear it.', '2465295065', '4008398120', 'Legendary', '5', null), ('2502422775', 'Tarantula', 'Linear Fusion Rifle', 'No one will escape my web.', '953998645', '4008398120', 'Legendary', '5', null), ('2505533224', 'Ghost Primus', 'Auto Rifle', 'The Ghost Primus was strong because of his disfigurement, not in spite of it. He alone had the vision to share my dream of a new, perfect world. Ghaul was a creature of singular beauty, and I loved him.', '1498876634', '4008398120', 'Legendary', '5', null), ('250721843', 'Abide the Return', 'Sword', '"It is what she asks of us." —Paladin Kamala Rior', '953998645', '4008398120', 'Legendary', '5', null), ('2508948099', 'Caretaker', 'Sword', 'All it takes is a little trust.', '953998645', '4008398120', 'Legendary', '5', null), ('2510526114', 'Unending Tempest', 'Submachine Gun', 'Now it''s worse and here to stay.', '1498876634', '4008398120', 'Legendary', '5', null), ('2513965917', 'Lunulata-4b', 'Combat Bow', 'I warn of the last moment.', '1498876634', '4008398120', 'Legendary', '5', null), ('2516360525', 'Purpose', 'Scout Rifle', '"You have not yet found your purpose. But it has found you." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('2517599010', 'Death Adder', 'Submachine Gun', 'You will not see me coming.', '2465295065', '4008398120', 'Legendary', '5', null), ('25228802', 'Refusal of the Call (Adept)', 'Glaive', 'Don''t listen.', '1498876634', '4008398120', 'Legendary', '5', null), ('2527666306', 'Igneous Hammer (Adept)', 'Hand Cannon', 'Forged by fire and might.', '2465295065', '4008398120', 'Legendary', '5', null), ('2531963421', 'No Reprieve', 'Shotgun', 'Sometimes mercy is worse.', '1498876634', '4008398120', 'Legendary', '5', null), ('253196586', 'Main Ingredient', 'Fusion Rifle', '"Now stir the sauce…"', '2465295065', '4008398120', 'Legendary', '5', null), ('2533990645', 'Blast Furnace', 'Pulse Rifle', 'Forged in the hottest fires.', '1498876634', '4008398120', 'Legendary', '5', null), ('2534546147', 'Lubrae''s Ruin', 'Glaive', 'Shape: Shattered', '2465295065', '4008398120', 'Legendary', '5', null), ('2535142413', 'Edge of Action', 'Glaive', 'An echo of an ancient weapon, forged from a memory of strength.', '2465295065', '2759499571', 'Exotic', '6', null), ('2535939781', 'The Mornin'' Comes', 'Sniper Rifle', 'Fix your eye upon the rising sun.', '2465295065', '4008398120', 'Legendary', '5', null), ('254156943', 'Dead Zone Rifle', 'Sniper Rifle', 'A rusted rifle you found in the EDZ mine. It''s old, but it still works.', '2465295065', '3340296461', 'Common', '2', null), ('2544285846', 'Scipio-D', 'Rocket Launcher', 'Battle for annihilation.', '953998645', '4008398120', 'Legendary', '5', null), ('2545083870', 'Apex Predator', 'Rocket Launcher', 'Is it you or I that tops the food chain, o challenger mine?', '953998645', '4008398120', 'Legendary', '5', null), ('254636484', 'Nezarec''s Whisper', 'Glaive', '"Rise, Disciple, and bear this gift with pride." —Rhulk, Disciple of the Witness', '2465295065', '4008398120', 'Legendary', '5', null), ('2553380021', 'Psychopomp (Adept)', 'Grenade Launcher', 'We''ll bring you home.', '2465295065', '4008398120', 'Legendary', '5', null), ('2553946496', 'Headstrong', 'Hand Cannon', 'Hawthorne forged this weapon out of scraps and salvage during her years alone in the wilds.', '1498876634', '3340296461', 'Common', '2', null), ('2553946497', 'Helios HC1', 'Hand Cannon', 'A standard issue Omolon weapon. City-made.', '2465295065', '3340296461', 'Common', '2', null), ('2558925366', 'Scatter Signal', 'Fusion Rifle', 'To the Voice on the other line.', '1498876634', '4008398120', 'Legendary', '5', null), ('2561659919', 'Antiope-D', 'Submachine Gun', 'They look to you to save them.', '1498876634', '4008398120', 'Legendary', '5', null), ('2563012876', 'Matador 64', 'Shotgun', 'Be the bull.', '2465295065', '4008398120', 'Legendary', '5', null), ('2563668388', 'Scalar Potential', 'Pulse Rifle', 'There''s power in perspective.', '2465295065', '4008398120', 'Legendary', '5', null), ('2566006935', 'Fioritura-59', 'Sidearm', 'SUROS invites you to embellish your accomplishments.', '2465295065', '4008398120', 'Legendary', '5', null), ('2573900604', 'Basso Ostinato', 'Shotgun', '"For centuries, the shotgun''s design has remained relatively constant. Shape, heft: an old pattern repeating in new machines." —Rohan', '2465295065', '4008398120', 'Legendary', '5', null), ('2575506895', 'Kindled Orchid', 'Hand Cannon', 'Find the beauty in the flame.', '2465295065', '4008398120', 'Legendary', '5', null), ('2575844666', 'Liminal Vigil', 'Sidearm', 'Cause and effect like a looped corridor. I stand. Ever watchful, forever.', '1498876634', '4008398120', 'Legendary', '5', null), ('2579693381', 'Cusp Sempiternal', 'Auto Rifle', 'Can you follow the terminator to its end?', '2465295065', '4008398120', 'Legendary', '5', null), ('2581162758', 'Enigma''s Draw', 'Sidearm', '"Indeed, I traffic in all kinds of secrets and mysteries. Weapons, as well." —Lakshmi-2', '1498876634', '4008398120', 'Legendary', '5', null), ('2581676735', 'New Land Beyond', 'Sniper Rifle', 'Every hit blazes the path to our reclamation.', '1498876634', '2759499571', 'Exotic', '6', null), ('2582755344', 'Seventh Seraph SAW', 'Machine Gun', 'Chained away long ago; its jaws too eager in times of peace.', '953998645', '4008398120', 'Legendary', '5', null), ('2584830733', 'Martyr''s Retribution', 'Grenade Launcher', 'That which returns from the void will always seek revenge.', '2465295065', '4008398120', 'Legendary', '5', null), ('2588048270', 'Spoiler Alert', 'Sidearm', 'Someone is going to die.', '1498876634', '4008398120', 'Legendary', '5', null), ('2591111628', 'Compass Rose', 'Shotgun', '"Let the Light be your compass." —Mithrax', '2465295065', '4008398120', 'Legendary', '5', null), ('2591241074', 'Strident Whistle', 'Combat Bow', 'Goes right through you.', '2465295065', '4008398120', 'Legendary', '5', null), ('2591257541', 'Scintillation', 'Linear Fusion Rifle', '"A paltry echo of the Ascendant Plane." —Toland, the Shattered', '953998645', '4008398120', 'Legendary', '5', null), ('2591586260', 'Allegro-34', 'Hand Cannon', 'SUROS invites you to pick up the pace.', '2465295065', '2127292149', 'Rare', '4', null), ('2591586261', 'Azimuth DSu', 'Hand Cannon', 'What lies beyond the horizon?', '1498876634', '2127292149', 'Rare', '4', null), ('2591586262', 'Lamia HC2', 'Hand Cannon', 'Make your enemy''s strength your own.', '2465295065', '2127292149', 'Rare', '4', null), ('2591586263', 'Ballyhoo Mk.27', 'Hand Cannon', 'Prepare to back up your boasts.', '1498876634', '2127292149', 'Rare', '4', null), ('2591746970', 'Leviathan''s Breath', 'Combat Bow', '"Cast a Shadow over the wilds of this universe. Return with glorious trophies." —Emperor Calus', '953998645', '2759499571', 'Exotic', '6', null), ('2595497736', 'The Enigma', 'Glaive', 'A weapon forged from an ancient memory, purpose-built for your hand.', '2465295065', '4008398120', 'Legendary', '5', null), ('2595813005', 'Taraxippos', 'Scout Rifle', 'A flash of green on the event horizon.', '1498876634', '4008398120', 'Legendary', '5', null), ('2598420927', 'Chroma Rush', 'Auto Rifle', 'Drink from the data stream.', '1498876634', '4008398120', 'Legendary', '5', null), ('2599338624', 'Liturgy', 'Grenade Launcher', 'It makes a circle.', '1498876634', '4008398120', 'Legendary', '5', null), ('2599338625', 'Bitter/Sweet', 'Grenade Launcher', 'The ravenous chorus sings through my veins.', '953998645', '4008398120', 'Legendary', '5', null), ('2603335652', 'Jurassic Green', 'Pulse Rifle', '"''Monster'' is a relative term. Just look at the Drifter."  —Glint', '2465295065', '4008398120', 'Legendary', '5', null), ('2603483885', 'Cloudstrike', 'Sniper Rifle', 'They return to moons devoid. Their eyes searching. It''s just begun. Meet this storm of sound and fury, till thunder-clashes fade to silence.', '2465295065', '2759499571', 'Exotic', '6', null), ('260532765', 'Duty Bound', 'Auto Rifle', '"Due respect, Commander? I was there when the Hive found us on Earth. I was there when we stopped them on Titan. And I''ll be there when we wipe them out." —Sloane', '1498876634', '4008398120', 'Legendary', '5', null), ('2605790032', 'Troubadour', 'Sniper Rifle', 'This weapon was forged by Devrim Kay VIII for the survivors.', '2465295065', '2395677314', 'Uncommon', '3', null), ('2605790033', 'Luna Nullis II', 'Sniper Rifle', 'The power you seek is in your hands.', '2465295065', '2395677314', 'Uncommon', '3', null), ('2605790034', 'Trondheim-LR2', 'Sniper Rifle', 'Wide rivers. Cold winters. Old songs. Find a way.', '2465295065', '2395677314', 'Uncommon', '3', null), ('2607304614', 'Empirical Evidence', 'Sidearm', 'Under duress, a soul will say whatever they think you want to hear. Trust your own eyes.', '1498876634', '4008398120', 'Legendary', '5', null), ('2611861926', 'Imminent Storm', 'Submachine Gun', 'It''s going to get worse before it gets better.', '1498876634', '4008398120', 'Legendary', '5', null), ('2621637518', 'Play of the Game', 'Grenade Launcher', 'Show no mercy.', '953998645', '4008398120', 'Legendary', '5', null), ('2625782212', 'Haunted Earth', 'Scout Rifle', '"Those we''ve lost still linger in every place we look. Earth is no place for the living." —Arach Jalaal', '1498876634', '4008398120', 'Legendary', '5', null), ('2625782213', 'Contingency Plan', 'Scout Rifle', '"The Traveler is an illusion. A false god. It will not save us. But this might." —Arach Jalaal', '2465295065', '4008398120', 'Legendary', '5', null), ('2631466936', 'Fortunate Star', 'Combat Bow', 'When it shines at dusk, luck will surely come your way.', '2465295065', '4008398120', 'Legendary', '5', null), ('2633186522', 'Shadow Price', 'Auto Rifle', 'A precision Auto Rifle left behind by Toland, the Shattered. It asks so little, and it offers so much.', '2465295065', '4008398120', 'Legendary', '5', null), ('2638190703', 'Aisha''s Embrace', 'Scout Rifle', 'Fill my wounds with molten gold and make me whole again.', '2465295065', '4008398120', 'Legendary', '5', null), ('2639921391', 'Nature Reclaimed', 'Scout Rifle', 'All natural, and all the deadlier for it.', '2465295065', '4008398120', 'Legendary', '5', null), ('2645567209', 'Fimbulwinter Stitch', 'Sidearm', 'Will you take us to the end?', '2465295065', '4008398120', 'Legendary', '5', null), ('2653171212', 'The Inquisitor', 'Shotgun', 'Ask the question.', '2465295065', '4008398120', 'Legendary', '5', null), ('2653171213', 'Astral Horizon', 'Shotgun', 'Even the brightest stars eventually set.', '1498876634', '4008398120', 'Legendary', '5', null), ('2653316158', 'Pillager', 'Submachine Gun', '"No mercy out here. Can''t afford it." —The Drifter', '1498876634', '4008398120', 'Legendary', '5', null), ('2659286158', 'Compact Defender', 'Sidearm', 'Perception is a metaphysical construct.', '2465295065', '4008398120', 'Legendary', '5', null), ('2660862359', 'Gentleman Vagabond', 'Sniper Rifle', 'Everyone loves a scoundrel.', '2465295065', '4008398120', 'Legendary', '5', null), ('2663204025', 'Subjunctive', 'Submachine Gun', 'Stop ''em? Pretty sure our deaths are just meant to be the early warning system.', '2465295065', '4008398120', 'Legendary', '5', null), ('2666273249', 'Hullabaloo', 'Grenade Launcher', 'Let''s make some noise.', '953998645', '4008398120', 'Legendary', '5', null), ('267089201', 'Warden''s Law (Adept)', 'Hand Cannon', 'Fight. Win. Li- Li- Li- Li- Li- FATAL EXCEPTION HAS OCCURRED AT 0028:C001E36', '1498876634', '4008398120', 'Legendary', '5', null), ('2671639706', 'Pure Poetry', 'Hand Cannon', 'Each line more potent than the last.', '1498876634', '4008398120', 'Legendary', '5', null), ('2671849376', 'Refusal of the Call', 'Glaive', 'Don''t listen.', '1498876634', '4008398120', 'Legendary', '5', null), ('2673925403', 'Irukandji', 'Sniper Rifle', 'My reach is deadly.', '1498876634', '4008398120', 'Legendary', '5', null), ('267672635', 'Backfang', 'Glaive', '"As sharp as Psion rotgut and twice as strong." —The Drifter', '2465295065', '4008398120', 'Legendary', '5', null), ('2680976411', 'Albedo Wing', 'Glaive', 'From this high up, the sunlight on snow looks like fire.', '2465295065', '4008398120', 'Legendary', '5', null), ('2681395357', 'Trackless Waste', 'Submachine Gun', '"No footprints out here." —Olu Alderdice', '1498876634', '4008398120', 'Legendary', '5', null), ('268260372', 'Regnant', 'Grenade Launcher', '"No one is hatched a Kell." —Mithrax', '953998645', '4008398120', 'Legendary', '5', null), ('268260373', 'Prodigal Return', 'Grenade Launcher', 'Pain persists in memory.', '2465295065', '4008398120', 'Legendary', '5', null), ('2683682446', 'Traitor''s Fate', 'Sword', 'Let the Emperor''s gratitude end your foes as swiftly as you have ended his.', '953998645', '4008398120', 'Legendary', '5', null), ('2683682447', 'Traitor''s Fate', 'Sword', 'The true Emperor of the Cabal invites you to strike down his faithless foe.', '953998645', '3340296461', 'Common', '2', null), ('2693941407', 'Older Sister III', 'Hand Cannon', '"To protect us, as she once protected me." —Executor Hideo', '2465295065', '4008398120', 'Legendary', '5', null), ('2694044460', 'Home Again', 'Auto Rifle', 'This weapon was forged by Devrim Kay VIII for the survivors.', '1498876634', '2395677314', 'Uncommon', '3', null), ('2694044461', 'Cydonia-AR1', 'Auto Rifle', 'A modded version of the Daito Cydonia, a Guardian standby.', '1498876634', '2395677314', 'Uncommon', '3', null), ('2694044462', 'SUROS Throwback', 'Auto Rifle', 'A heavily modded version of a SUROS prototype weapon.', '1498876634', '2395677314', 'Uncommon', '3', null), ('2694044463', 'Jiangshi AR1', 'Auto Rifle', 'A modded version of the Omolon Jiangshi, a Guardian standby.', '2465295065', '2395677314', 'Uncommon', '3', null), ('2694576561', 'Two-Tailed Fox', 'Rocket Launcher', 'Adorably murderous.', '953998645', '2759499571', 'Exotic', '6', null), ('2697058914', 'Komodo-4FR', 'Linear Fusion Rifle', 'I await the perfect moment and watch my enemies decay.', '953998645', '4008398120', 'Legendary', '5', null), ('2697143634', 'Lotus-Eater (Adept)', 'Sidearm', 'Let it all go.', '2465295065', '4008398120', 'Legendary', '5', null), ('2699423382', 'MIDA Macro-Tool', 'Shotgun', 'Select application: Geiger counter. Broiler. Auto-pilot. Emotional support weapon. List continues.', '2465295065', '4008398120', 'Legendary', '5', null), ('2700862856', 'Foggy Notion', 'Submachine Gun', '"Hard to make it out, just a blur of bullets and fists."', '2465295065', '4008398120', 'Legendary', '5', null), ('2700862858', 'Out of Options', 'Submachine Gun', '"All you really need is two."', '2465295065', '4008398120', 'Legendary', '5', null), ('2700862859', 'Red Mamba', 'Submachine Gun', 'My venom is swift.', '2465295065', '4008398120', 'Legendary', '5', null), ('2703340117', 'Somerled-D', 'Shotgun', 'Heroes are not born, but made.', '2465295065', '4008398120', 'Legendary', '5', null), ('270610849', 'Mistral Lift', 'Linear Fusion Rifle', 'The unceasing cold without. The glowing hearth within.', '953998645', '4008398120', 'Legendary', '5', null), ('2707464805', 'Zenith of Your Kind', 'Shotgun', '"Earth has no Shadow. Not yet." —Calus, Emperor of the Cabal', '2465295065', '4008398120', 'Legendary', '5', null), ('2708806099', 'BxR-55 Battler', 'Pulse Rifle', 'A treasured competition piece from a bygone era.', '2465295065', '4008398120', 'Legendary', '5', null), ('2712244741', 'Bygones', 'Pulse Rifle', '"Gone, but never forgotten." —The Drifter', '1498876634', '4008398120', 'Legendary', '5', null), ('2712683313', 'Abyssal Edge (Adept)', 'Sword', 'Crease the universe.', '953998645', '4008398120', 'Legendary', '5', null), ('2714022207', 'Corsair''s Wrath', 'Linear Fusion Rifle', '"We are only briefly Awoken. The rest of existence is an eternal dream." —Sedia', '953998645', '4008398120', 'Legendary', '5', null), ('2715240478', 'Riptide', 'Fusion Rifle', '"Sudden, swift, and deadly."', '1498876634', '4008398120', 'Legendary', '5', null), ('2720651699', 'Zealot''s Reward', 'Fusion Rifle', '"Why not use these gifts we''ve been given?" —Yardarm-4, Titan of the Kentarch 3', '2465295065', '4008398120', 'Legendary', '5', null), ('2721157927', 'Tarnation', 'Grenade Launcher', 'Welcome to hell on Earth… delivered at 250 feet per second!', '953998645', '4008398120', 'Legendary', '5', null), ('2721249463', 'Tyranny of Heaven', 'Combat Bow', 'It was She that inspired me to imagine your destruction, o jailer mine.', '2465295065', '4008398120', 'Legendary', '5', null), ('2723241847', 'Patron of Lost Causes', 'Scout Rifle', 'There is a rough engraving on its side: "In Memoriam."', '1498876634', '4008398120', 'Legendary', '5', null), ('2723909519', 'Arc Logic', 'Auto Rifle', '"The Hive live by sword logic. Teach them another way." —Eris Morn', '2465295065', '4008398120', 'Legendary', '5', null), ('2725426834', 'Intercalary', 'Auto Rifle', 'The future is closer than you think.', '1498876634', '4008398120', 'Legendary', '5', null), ('2725894221', 'Folded Root', 'Rocket Launcher', 'Enjoy the simple things, even your demise.', '953998645', '4008398120', 'Legendary', '5', null), ('2728851518', 'Glacioclasm', 'Fusion Rifle', 'Clear and cold, forever.', '2465295065', '4008398120', 'Legendary', '5', null), ('2730671571', 'Terminus Horizon', 'Machine Gun', 'If something heavy''s coming in, send something heavy back out.', '953998645', '4008398120', 'Legendary', '5', null), ('273396910', 'Frontier Justice', 'Scout Rifle', '"…and after that, there will be time for questions."', '1498876634', '4008398120', 'Legendary', '5', null), ('2734369894', 'Stay Away', 'Grenade Launcher', 'Hawthorne forged this weapon out of scraps and salvage during her years alone in the wilds.', '2465295065', '3340296461', 'Common', '2', null), ('2738174948', 'Distant Tumulus', 'Sniper Rifle', '"Who will speak for us when we are gone?" —Arach Jalaal', '2465295065', '4008398120', 'Legendary', '5', null), ('2738601016', 'Cataphract GL3', 'Grenade Launcher', 'Inexorable force is the quickest path between two destinations.', '953998645', '4008398120', 'Legendary', '5', null), ('2742490609', 'Death Adder', 'Submachine Gun', 'You will not see me coming.', '2465295065', '4008398120', 'Legendary', '5', null), ('2742838700', 'True Prophecy', 'Hand Cannon', '"Some claim to know the future better than we do. Listen carefully. Then ask yourself: do their words ring true or false?" —Lakshmi-2', '1498876634', '4008398120', 'Legendary', '5', null), ('2742838701', 'Dire Promise', 'Hand Cannon', '"If you think this world ends well, you are mistaken." —Arach Jalaal', '1498876634', '4008398120', 'Legendary', '5', null), ('2744715540', 'Bug-Out Bag', 'Submachine Gun', 'Grab and go.', '2465295065', '4008398120', 'Legendary', '5', null), ('2753269585', 'Tempered Dynamo', 'Fusion Rifle', 'Reinforce the bonds of legacy.', '2465295065', '4008398120', 'Legendary', '5', null), ('2755584425', 'Refusal of the Call (Adept)', 'Glaive', 'Don''t listen.', '1498876634', '4008398120', 'Legendary', '5', null), ('2759251821', 'Unwavering Duty (Adept)', 'Machine Gun', '"There''s no one else I can trust with her care." —Ikora Rey', '953998645', '4008398120', 'Legendary', '5', null), ('2759590322', 'THE SWARM', 'Machine Gun', 'Hunger is the all of it, and it is all of hunger.', '953998645', '4008398120', 'Legendary', '5', null), ('276080079', 'Exile''s Curse (Adept)', 'Fusion Rifle', 'It''s a blessing in disguise.', '2465295065', '4008398120', 'Legendary', '5', null), ('2760833884', 'Cold Comfort', 'Rocket Launcher', '"Do not be afraid."', '953998645', '4008398120', 'Legendary', '5', null), ('2761869150', 'Ignition Code', 'Grenade Launcher', '"I can decode anything with a grenade launcher." —Saint-14', '1498876634', '4008398120', 'Legendary', '5', null), ('2763843898', 'Midnight Coup', 'Hand Cannon', 'The conspirators were too afraid to kill me—rightly so. I am the beloved father of the people, and the glorious mob would not suffer my death. My sentence was exile.', '1498876634', '4008398120', 'Legendary', '5', null), ('2763843899', 'Luna''s Howl', 'Hand Cannon', '"Guardians never die. But we don''t forget those who do." —Lord Shaxx', '2465295065', '4008398120', 'Legendary', '5', null), ('2764074355', 'A Sudden Death (Adept)', 'Shotgun', '"Everything dies. This is proof." —Emissary of the Nine', '2465295065', '4008398120', 'Legendary', '5', null), ('2765451288', 'Synanceia', 'Sword', 'Don''t get too close.', '953998645', '4008398120', 'Legendary', '5', null), ('2765451289', 'Synanceia', 'Sword', 'Don''t get too close.', '953998645', '4008398120', 'Legendary', '5', null), ('2765451290', 'Synanceia', 'Sword', 'Don''t get too close.', '953998645', '4008398120', 'Legendary', '5', null), ('2765451291', 'Synanceia', 'Sword', 'Don''t get too close.', '953998645', '4008398120', 'Legendary', '5', null), ('2767393525', 'Nox Perennial V', 'Fusion Rifle', 'Truth endures beneath the surface froth of time.', '1498876634', '4008398120', 'Legendary', '5', null), ('276918162', 'Hagakure', 'Sword', 'The way of the warrior is death.', '953998645', '4008398120', 'Legendary', '5', null), ('2770035786', 'M-17 "Fast Talker"', 'Submachine Gun', 'Imperium tech-based firearm common among syndicates vying for control in the Lawless Frontier.', '1498876634', '4008398120', 'Legendary', '5', null), ('2776503072', 'Royal Chase', 'Scout Rifle', '"If anyone asks why you''re out here, just reload." —Devrim Kay', '2465295065', '4008398120', 'Legendary', '5', null), ('2778013407', 'Firefright', 'Auto Rifle', 'What''s the scariest part of a firefight? The whole damn thing.', '1498876634', '4008398120', 'Legendary', '5', null), ('2779821308', 'Brya''s Love', 'Scout Rifle', '"Just promise me one thing… Don''t look back." —Brya', '2465295065', '4008398120', 'Legendary', '5', null), ('2782325300', 'Quickfang', 'Sword', 'My smile is full of blades.', '953998645', '4008398120', 'Legendary', '5', null), ('2782325301', 'Eternity''s Edge', 'Sword', '"A sword is a wand that casts two spells: parry 