riend.', '1498876634', '4008398120', 'Legendary', '5', null), ('3325463374', 'Thunderlord', 'Machine Gun', 'They return from fields afar. The eye has passed, the end nears. Do not fade quietly. Let thunder reign again.', '953998645', '2759499571', 'Exotic', '6', null), ('3325744914', 'Inaugural Address', 'Pulse Rifle', 'My first act as emperor was to send the Consul into the wasteland. The golden sun would burn away his corrupt form—a fitting symbol for the revolution that was to be my reign.', '2465295065', '4008398120', 'Legendary', '5', null), ('3325778512', 'A Fine Memorial', 'Machine Gun', '"Thousands of Guardians fell to Crota and the Hive. Thousands." —Eris Morn', '953998645', '4008398120', 'Legendary', '5', null), ('3326850591', 'The Long Walk', 'Sniper Rifle', '"There is an end to everything." —Emissary of the Nine', '2465295065', '4008398120', 'Legendary', '5', null), ('3328019216', 'Arcane Embrace', 'Shotgun', 'Channel an aura of control over the energies of the universe.', '2465295065', '4008398120', 'Legendary', '5', null), ('3329218848', 'Judgment (Adept)', 'Hand Cannon', '"The greatest threat to a Guardian is another Guardian." —Emissary of the Nine', '1498876634', '4008398120', 'Legendary', '5', null), ('3329842376', 'Memory Interdict', 'Grenade Launcher', '"I have no time for nostalgia. Give me visions of braided futures, brilliantly aflame." —Lakshmi-2', '953998645', '4008398120', 'Legendary', '5', null), ('3332125295', 'Aisha''s Care (Adept)', 'Pulse Rifle', 'Reassurance. Restraint. A hand on the shoulder, offering both.', '1498876634', '4008398120', 'Legendary', '5', null), ('3334276332', 'Vestian Dynasty', 'Sidearm', '"Long live the Queen." —Petra Venj', '2465295065', '4008398120', 'Legendary', '5', null), ('3334276333', 'Death by Scorn', 'Sidearm', '"The Barons fight together." —Elykris, transl. from Eliksni', '2465295065', '4008398120', 'Legendary', '5', null), ('3335343363', 'Tarantula', 'Linear Fusion Rifle', 'No one will escape my web.', '9