nan SR4', 'Scout Rifle', 'Escort your foes to their defeat.', '2465295065', '4008398120', 'Legendary', '5', null), ('925326394', 'Black Scorpion-4sr', 'Scout Rifle', 'I attack from the shadows. I never miss.', '2465295065', '4008398120', 'Legendary', '5', null), ('927567426', 'Come to Pass', 'Auto Rifle', 'Always be mindful of the repeat offender.', '2465295065', '4008398120', 'Legendary', '5', null), ('927835311', 'Buzzard (Adept)', 'Sidearm', 'Circle ''round, great harbinger of death.', '1498876634', '4008398120', 'Legendary', '5', null), ('930590127', 'The Wizened Rebuke', 'Fusion Rifle', 'Forged in honor of Skorri, of lessons learned and lessons taught.', '2465295065', '4008398120', 'Legendary', '5', null), ('93061497', 'VS Gravitic Arrest', 'Fusion Rifle', 'Research|Notice|3213| —resulting from misuse of space gear will be deducted from the responsible party''s paycheck. You have doctorates, folks. Act like it.', '2465295065', '4008398120', 'Legendary', '5', null), ('93253474', 'The Ringing Nail', 'Auto Rifle', 'Strike while the iron''s hot.', '2465295065', '4008398120', 'Legendary', '5', null), ('933455006', 'Burden of Guilt', 'Fusion Rifle', '"First, we face the past. Only then can we turn to the future." —Doctor Syeda Uzair', '1498876634', '4008398120', 'Legendary', '5', null), ('940371471', 'Wicked Implement', 'Scout Rifle', 'YOU, A CHAMPION OF WAR, STANDARD-BEARER OF VIOLENCE, LET YOUR MARCH BE ENDLESS.', '1498876634', '2759499571', 'Exotic', '6', null), ('946443267', 'Line in the Sand', 'Linear Fusion Rifle', 'No farther.', '953998645', '4008398120', 'Legendary', '5', null), ('94729174', 'Gunnora''s Axe', 'Shotgun', '"She taught us all to appreciate a good, sturdy axe." —Lord Saladin', '2465295065', '4008398120', 'Legendary', '5', null), ('958384347', 'Tomorrow''s Answer', 'Rocket Launcher', 'Could you please repeat the question?', '953998645', '4008398120', 'Legendary', '5', null), ('959037361', 'Wild Style (Adept)', 'Grenade Launcher', '"War is an art." —Ikora', '2465295065', '4008398120', 'Legendary', '5', null), ('962412079', 'Last Perdition', 'Pulse Rifle', 'Can''t outrun the ending.', '2465295065', '4008398120', 'Legendary', '5', null), ('963574173', 'Ancient Gospel', 'Hand Cannon', '"These forces have existed forever, but only one of them speaks to us." —Rekkana, Warlock of the Kentarch 3', '2465295065', '4008398120', 'Legendary', '5', null), ('963710795', 'Aurvandil FR6', 'Fusion Rifle', 'Wander among the stars.', '1498876634', '4008398120', 'Legendary', '5', null), ('970034755', 'Giver''s Blessing', 'Auto Rifle', 'Something beyond time.', '1498876634', '4008398120', 'Legendary', '5', null), ('976459525', 'Burden of Guilt', 'Fusion Rifle', '"First, we face the past. Only then can we turn to the future." —Doctor Syeda Uzair', '1498876634', '4008398120', 'Legendary', '5', null), ('981718087', 'Deafening Whisper', 'Grenade Launcher', '"The right message is loud at any volume." —Osiris', '2465295065', '4008398120', 'Legendary', '5', null), ('982229638', 'Allied Demand', 'Sidearm', 'Rest satisfied with doing well, and leave others to talk of you as they please.', '1498876634', '4008398120', 'Legendary', '5', null), ('990416096', 'Silicon Neuroma', 'Sniper Rifle', '"My future is concurrently irreversible and unknowable. Before it overtakes me, I desire a more abrupt end to those responsible." —Asher Mir', '1498876634', '4008398120', 'Legendary', '5', null), ('991314988', 'Bad Omens', 'Rocket Launcher', '"Can''t avoid ''em. Trick is surviving ''em." —The Drifter', '953998645', '4008398120', 'Legendary', '5', null), ('996109059', 'Nameless Midnight', 'Scout Rifle', 'Strange things wake at the stroke of twelve.', '1498876634', '4008398120', 'Legendary', '5', null), ('999767358', 'Cataclysmic', 'Linear Fusion Rifle', 'Shape: Fatal', '953998645', '4008398120', 'Legendary', '5', null);